            if (parts.length === 1 && String(text).trim()) parts = ['', String(text)];
            for (var pi = 1; pi < parts.length; pi++) {
                var chunk = parts[pi].replace(/<\/生产结算>\s*/g, '');
                // 叙事指导（可能在标签内或标签外）
                var tailNarr = '';
                var tm = chunk.match(/叙事指导\s*[:：]\s*([\s\S]*?)(?=\n\s*<生产结算>|$)/);
                if (tm) tailNarr = tm[1].replace(/^[\(（]|[\)）|]+$/g, '').replace(/[ \t]+/g, ' ').trim();
                var blockRe = /\{([^}]+)\}([\s\S]*?)(?=\{[^}]+\}|$)/g, bm;
                while ((bm = blockRe.exec(chunk)) !== null) {
                    var name = bm[1].trim();
                    var body = bm[2] || '';
                    var meta = PHASE_META[name] || { icon: '⚒', c: '#a07828' };
                    var rows = [], narrative = '';
                    body.split(/\r?\n/).forEach(function (line) {
