        /* ===== 同伴装备按钮（椭圆形·更醒目·可交互） ===== */
        .jrpg-comp-equip-btn{
            display:inline-flex; align-items:center; gap:4px;
            background:linear-gradient(180deg,#f6c945,#e0a61f);
