        // 出生年月日 → 当前年龄（按 世界.日期 自动计算；解析 "圣光历1467年3月1日" / "1467-03-01"）
        // 出生年月日一经确定不改；年龄不再由 AI/手动改写（命令层另有只读守卫）
        function parseEraDate(str) {
            var s = String(str || '').trim();
            if (!s) return null;
            // 严格格式优先（带分隔）：1467-03-01 / 1467/3/1 / 1467年3月1日
            var m = s.match(/(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})/);
            // 中文宽松兜底（必须带"年"字）：1467年3月 / 圣光历1467年3月1日
            if (!m) m = s.match(/(\d{3,4})年\s*(\d{1,2})?月\s*(\d{1,2})?日?/);
            if (!m) return null;
            return { y: parseInt(m[1], 10), mo: parseInt(m[2] || 1, 10), d: parseInt(m[3] || 1, 10) };
        }
        function calcActorAge(actor) {
            try {
                if (!actor || typeof actor !== 'object') return null;
                var birth = parseEraDate(actor.出生年月日);
                if (!birth) return (parseInt(actor.年龄, 10) > 0 ? parseInt(actor.年龄, 10) : null);
                var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
                var nowStr = _.get(all, 'stat_data.世界.日期', '') || '';
                var now = parseEraDate(nowStr);
                if (!now) return null;
                var age = now.y - birth.y;
                if (now.mo < birth.mo || (now.mo === birth.mo && now.d < birth.d)) age -= 1;
                return Math.max(0, age);
            } catch (e) { return null; }
        }
        function relmapDetailHtml(name, v) {
            var fav = _.clamp(parseInt(v.好感度, 10) || 0, -100, 100);
            var h = '<div class="tt">' + escapeAttr(name) + ' <span style="color:' + relmapFavColor(fav) + ';">♥ ' + fav + '</span></div>';
            if (v.身份) h += '<div class="row">🪪 身份：' + escapeAttr(v.身份) + '</div>';
            if (v.当前位置) h += '<div class="row">📍 当前位置：' + escapeAttr(v.当前位置) + '</div>';
            // 年龄：有出生年月日 → 按当前日期自动计算（不再手动维护）；出生年月日单独成栏
            var vAge = calcActorAge(v);
            if (v.出生年月日) h += '<div class="row">📅 出生年月日：' + escapeAttr(v.出生年月日) + '</div>';
            if (vAge !== null && vAge !== undefined) {
                h += '<div class="row">🎂 年龄：' + escapeAttr(String(vAge)) + '岁</div>';
            }
            if (v.关系描述) h += '<div class="ttl">💬 关系</div><div>' + escapeAttr(v.关系描述) + '</div>';
            if (v.关键事件) h += '<div class="ttl">⚔ 关键事件</div><div>' + escapeAttr(v.关键事件) + '</div>';
            var tl = Array.isArray(v.关系时间线) ? v.关系时间线 : [];
            if (tl.length) {
                h += '<div class="ttl">📜 关系时间线</div>';
                tl.forEach(function (t) {
                    if (t && (t.时间 || t.事件)) {
                        h += '<div class="tl">' + (t.时间 ? '<span>[' + escapeAttr(t.时间) + ']</span>' : '') + escapeAttr(t.事件 || '') + '</div>';
                    }
                });
            }
            if (v.心里话) h += '<div class="ttl">💭 心里话</div><div style="font-style:italic;">"' + escapeAttr(v.心里话) + '"</div>';
            return h;
        }
                                // 自我状态美化：判定增益/减益/中性（优先条目类型字段，缺失按名称关键词兜底）
        function relmapStatusMeta(v, name) {
            var type = (v && v.类型) ? v.类型 : '中性';
            if (type !== '增益' && type !== '减益') {
                var bad = /中毒|灼烧|冰冻|麻痹|诅咒|虚弱|流血|眩晕|昏迷|压制|恐惧|混乱|束缚|沉默|疲劳|中毒|致盲|减速/;
                var good = /祝福|守护|护盾|振奋|鼓舞|加速|再生|圣光|护体|增益|力量/;
                if (bad.test(name || '')) type = '减益';
                else if (good.test(name || '')) type = '增益';
                else type = '中性';
            }
            return {
                type: type,
                icon: type === '增益' ? '✨' : (type === '减益' ? '⚠️' : '▪️'),
                color: type === '增益' ? '#27ae60' : (type === '减益' ? '#c0392b' : '#7f8c8d'),
                label: type === '增益' ? '增益' : (type === '减益' ? '减益' : '中性')
            };
        }
        function renderRelationMap() {
