        async function trtSlotRemove(terrName, bName) {
            if (typeof toastr !== 'undefined' && !confirm('确认拆除「' + bName + '」？（加成将回退）')) return;
            await trtWriteTerritory(terrName, function(t2) {
                var bc = _.get(t2, '建筑.已建造', {}) || {};
                delete bc[bName];
                _.set(t2, '建筑.已建造', bc);
            });
            trtInjectToContext('💥【建筑拆除】' + terrName + ' 拆除了【' + bName + '】',
                '请按「领地发展·变量更新规则」回退该建筑对应的加成（增长倍率），并在叙事中体现拆除后果。');
            if (typeof toastr !== 'undefined') toastr.success('已拆除「' + bName + '」', '领地');
            renderTerritoryPanel();
        }
        function renderTerritoryPanel() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var terrOn = !!_.get(all, 'stat_data.$flags.领地建设', false);
            var territories = _.get(all, 'stat_data.领地', {}) || {};
            var hasData = Object.keys(territories).length > 0;
            var $tabBtn = $('.jrpg-tab-btn[data-tab="tab-territory"]');
            if ($tabBtn.length) $tabBtn.css('display', (terrOn || hasData) ? '' : 'none');
            var $box = $('#territory-inner');
            if (!$box.length) return;
            trtApplyTheme();
            var keys = Object.keys(territories);
            if (!keys.length) {
                $box.html('<div class="jrpg-list-empty">暂无领地。在首页开启「领地建设」且玩家成为统治者（国王/公爵/男爵/权臣等）后，这里将显示领地数据。</div>');
                return;
