            var html = '';
            html += '<div class="trt-settings"><button class="trt-set-btn" id="trt-theme-btn" title="切换美化主题">🎨 主题</button><div class="trt-theme-menu" id="trt-theme-menu">';
            Object.keys(TRT_THEMES).forEach(function(k) {
                html += '<button class="trt-theme-item' + (trtTheme() === k ? ' active' : '') + '" data-trt-theme="' + k + '">' + TRT_THEMES[k] + '</button>';
            });
            html += '</div></div>';
            keys.forEach(function(name) {
                var t = territories[name] || {};
                var tier = t.规模等级 || '村庄';
                var variant = t.变种 || '';
                var race = _.get(t, '建筑.种族', '') || '';
                html += '<div class="trt-panel">';
                html += '<div class="trt-title">🏰 ' + escapeAttr(name) + '<span class="trt-sub">' + escapeAttr(tier) + (variant ? ' · ' + escapeAttr(variant) : '') + (race ? ' · ' + (TRT_RACE_ICONS[race] || '') + race : '') + '</span></div>';
                var fields = [['👥 人口', '人口'], ['🛡️ 军队', '军队'], ['🔬 科技水平', '科技水平'], ['⚖️ 政治派系', '政治派系'], ['🌾 资源', '资源'], ['🤝 外交', '外交'], ['💰 经济', '经济']];
                html += '<div class="trt-grid">';
                fields.forEach(function(f) {
                    html += '<div class="trt-block"><div class="trt-block-title">' + f[0] + '</div>' + renderTerritoryField(f[1], t[f[1]], '领地.' + name + '.' + f[1]) + '</div>';
                });
                html += '</div>';
                html += renderTrtSlots(t, name);
                html += '<div class="trt-divider">❖ ❖ ❖</div>';
                html += '<div class="trt-block-title" style="font-size:13px;">🏗️ 建筑与建设</div>';
                html += '<div id="trt-buildings-' + escapeAttr(name).replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_') + '">' + renderTrtBuildings(t, name) + '</div>';
                html += '<div class="trt-divider">❖ ❖ ❖</div>';
                html += '<div class="trt-block-title" style="font-size:13px;">🔬 科技树</div>';
