            "不死人": [
                { lvl: 1, n: "余烬之躯", c: 1, d: "[被动·核心] 你不会真正死亡。HP归零时，灵魂残留在最近的「篝火」（本源锚点）处重燃，恢复50%HP与全部SP。重生后敌人仇恨重置。每次长休限用3次，超过则需找到篝火处手动休整恢复。" },
                { lvl: 1, n: "黑色铠甲", c: 1, d: "[被动] 全身被漆黑的全覆式铠甲笼罩，不见面容。基础防御+3，对毒素、流血、诅咒拥有基础抗性（减免50%）。因铠甲沉重，游泳速度减半。" },
                { lvl: 1, n: "全能武备", c: 1, d: "[被动] 作为战斗人偶的万能适配体质，可熟练使用一切简易/军用武器、轻甲/中甲/重甲。切换武器不消耗额外动作。" },
                { lvl: 3, n: "篝火传承", c: 2, d: "[动作] 在篝火（本源锚点）处休整至少10分钟，恢复全部HP/SP，重置余烬之躯的使用次数，并清除所有非诅咒类负面状态。同一篝火每日限用1次。" },
                { lvl: 3, n: "战斗翻滚", c: 2, d: "[反应] SP2。受击前瞬间向前方或侧方翻滚闪避，本轮内物理攻击防御+5（翻滚无敌帧）。翻滚后若紧接近战攻击，该攻击检定+2。" },
                { lvl: 3, n: "韧性意志", c: 2, d: "[被动] 战斗人偶的躯壳不会被轻易打断。受到攻击时不会因伤害而失去动作连贯性（免疫攻击中断和击退），且硬直时间减半。" },
                { lvl: 5, n: "处决", c: 3, d: "[主动] SP3。对陷入倒地、眩晕、束缚或失衡状态的敌人发动致命一击。该次攻击自动暴击，伤害骰取最大值。若目标等阶不高于自身，直接触发即死判定——力量豁免DC(8+力量修正)，失败则被一击毙命。" },
                { lvl: 5, n: "灵魂附魔", c: 3, d: "[附赠] SP2。将本源意志的碎片短暂附着于武器上，持续3轮。可选择：火焰（+2d6火伤/对魔族+1d6）、暗月（+2d6力场/穿透护盾）、雷电（+2d6雷伤/暴击范围+1）。切换附魔需重新消耗SP。" },
                { lvl: 5, n: "余火状态", c: 3, d: "[主动] SP4。激活体内残存的本源之力，铠甲缝隙中透出橙红色余烬光芒，持续5轮。期间：HP上限+30%，近战攻击额外+1d8火伤，移动速度+10尺。结束后陷入1级力竭。" },
                { lvl: 7, n: "武器质变", c: 4, d: "[被动·升级] 在篝火处可花费10分钟重塑手中武器的属性。包括：厚重（力量修正+2）、锋利（敏捷修正+2）、熟练（双修正取高）、雷电（附加雷伤）、火焰（附加火伤）、暗月（附加力场穿透）。每次仅能维持一种质变，可随时在篝火切换。" },
                { lvl: 7, n: "盾反", c: 4, d: "[反应] SP3。持盾时在受击瞬间精准格挡。成功则完全抵消该次近战伤害，并使攻击者陷入1轮大硬直（可接【处决】）。对大型及以上体型敌人的盾反仅抵消伤害，不造成硬直。" },
                { lvl: 7, n: "原力迸发", c: 4, d: "[主动] SP3。从铠甲中爆发出一圈无形的冲击波，击退周围10尺内所有敌人，造成2d6+力量修正的力场伤害。敏捷豁免DC14失败者倒地。" },
                { lvl: 9, n: "幽邃灵魂", c: 5, d: "[被动] 在篝火处长休后，获得临时的「幽邃记忆」——可选择一项基础属性+2（持续至下次篝火长休），或习得一种消耗性技能（由GM裁定）。幽邃记忆随篝火长休重置。" },
                { lvl: 9, n: "血源回响", c: 5, d: "[被动] 每亲手击杀一个敌人，恢复1d6HP与1SP。击杀精英/首领级敌人时，额外获得一个暂时性的「灵魂碎片」——可储存最多3枚，每枚可在篝火长休时兑换为等级×2的额外经验值或一项临时增益。" },
                { lvl: 9, n: "大剑精通", c: 5, d: "[被动] 双手持重型武器（大剑/大斧/大锤）时，攻击检定+2，伤害骰+1d6。且每次命中可打断正在蓄力的敌方术式（需力量对抗）。" },
                { lvl: 11, n: "钢铁守护", c: 6, d: "[主动] SP5。将黑色铠甲化为绝对壁垒，持续2轮。期间：防御+8，免疫一切物理暴击和背刺，所有元素抗性+50%。但移动速度减半，且无法翻滚。" },
                { lvl: 11, n: "余烬爆发", c: 6, d: "[被动·升级] 余火状态下，每次近战命中触发小范围爆炸（半径5尺），对周围敌人造成2d6火伤。且余火状态持续时间延长至8轮，力竭降级消失。" },
                { lvl: 11, n: "双持战技", c: 6, d: "[被动] 可双持两把非重型的武器，进行双武器战斗时副手攻击不再减值，且主手命中后可用附赠动作立刻追加一次副手攻击。" },
                { lvl: 13, n: "薪王化身", c: 7, d: "[主动] SP8。彻底点燃体内的本源碎片，铠甲缝隙喷涌出金色的火焰。全属性+3，所有武器攻击附带3d8神圣火焰伤害，免疫一切恐惧/魅惑/即死，移动速度翻倍，持续5轮。每日1次。持续期间每秒流失最大HP的2%，可提前解除。" },
                { lvl: 13, n: "古达之握", c: 7, d: "[主动] SP5。伸出一只由本源之力凝聚的黑色巨手，抓住30尺内一名中型或以下体型的目标。目标力量豁免DC18，失败则被拖拽至身前并陷入倒地状态，可立即接【处决】。对大型目标仅造成3d8力场伤害并拖近15尺。" },
                { lvl: 15, n: "幽邃教堂", c: 8, d: "[主动] SP10。以自身为中心展开半径30尺的幽邃领域，持续4轮。领域内：所有友方每轮恢复1d8+感知修正HP；所有敌方受到暗属性压制——攻击检定-2，速度减半；领域中心的你获得+4全属性抗性。每日1次。" },
                { lvl: 15, n: "不死人契约", c: 8, d: "[被动] 契约·不死人的信条：每次死亡不再是终点。余烬之躯的使用次数上限提升至5次/长休；篝火传承的休整时间缩短为5分钟；在非战斗状态下，每10分钟自动恢复5%最大HP。" },
                { lvl: 17, n: "无尽轮回·篝火永燃", c: 9, d: "[被动·升级] 即便余烬之躯次数用尽，你也不会真正消亡——取而代之的是在原地化为一团灰烬，2轮后重塑躯体（以25%HP复活）。此能力每日限1次。同时所有篝火处恢复效果翻倍。" },
                { lvl: 17, n: "黑焰剑技", c: 9, d: "[主动] SP8。向武器中注入最纯粹的本源暗焰，下一击附加6d8暗火混合伤害。若此击击杀目标，其灵魂被短暂禁锢——可作为一次性「篝火燃料」，立刻重置一次余烬之躯的使用次数。" },
                { lvl: 19, n: "传火终局·初火熄灭", c: 10, d: "[主动] 1次/永久。以自身全部余烬为代价，将黑色铠甲内的本源核心彻底引爆。以自身为中心半径1000尺内的一切被魔潮污染的造物受到80d10神圣火焰伤害（无豁免），地表的魔潮浓度被永久清零。施放者本人的铠甲碎裂、躯体化为灰烬飘散——但若在引爆前曾于某处篝火留下灵魂碎片，则碎片可在数日后重塑一具新的躯壳（失去全部记忆与等级，从Lv.1重新开始）。若未留下碎片，则真正意义上的死亡。" }
            ],
            "魔王": [
                { lvl: 1, n: "法则拟态武装", c: 1, d: "[被动] 攻击伤害类型与距离随拟态武器/魔法瞬息变化，造成4d10+12真实伤害。" },
                { lvl: 1, n: "万象拟态", c: 1, d: "[被动] 可完美复刻任何曾被魔潮吞噬或接触过的生物形态、技能与权能。" },
                { lvl: 1, n: "命格权能·魔潮指令", c: 1, d: "MP20 | 强制唤醒并强化半径500尺内所有魔族与魔兽，使其获得史诗级增益。" },
                { lvl: 3, n: "命格机制·绝对遮蔽", c: 2, d: "[被动] 免疫一切探查魔法与神术，针对他的先手突袭被强行偏移。" },
                { lvl: 5, n: "神格·渊神制裁", c: 3, d: "神术 | 8d10+15扭曲光辉，无法通过抗性减免，命中后削减目标HP上限。" },
                { lvl: 5, n: "神明躯壳", c: 3, d: "[被动] 免疫暴击、异常状态、即死判定与物理破甲。" },
                { lvl: 7, n: "信仰回流", c: 4, d: "[被动] 只要有信徒祈祷，每轮自动恢复50点HP。" },
                { lvl: 9, n: "神权·异端剥夺", c: 5, d: "12d10真实伤害，意志豁免DC24失败则丧失一切加护/魔法/武技3轮。" },
                { lvl: 9, n: "渊神领域", c: 5, d: "[被动] 半径100尺内敌方HP/MP恢复减半，每轮承受精神污染。" },
                { lvl: 13, n: "三源命核终末", c: 7, d: "[被动] 最终形态，1500HP，概念级污染源，攻击附带反弹腐蚀。" },
                { lvl: 13, n: "遗民哀嚎", c: 7, d: "10d8精神伤害，半径100尺，意志豁免DC24否则恐惧。" },
                { lvl: 17, n: "腐败触须横扫", c: 9, d: "8d12+20钝击，攻击范围30尺，命中附带击倒与吞噬判定。" },
                { lvl: 19, n: "概念侵蚀", c: 10, d: "[被动] 任何对其造成近战物理伤害的攻击者，受到2d6反弹腐蚀伤害。" }
            ],
            "德鲁伊": [
                { lvl: 1, n: "自然感知", c: 1, d: "[被动] 感知半径30尺内所有植物与动物的位置和状态；野外生存检定+2" },
                { lvl: 1, n: "荆棘射击", c: 1, d: "MP2 | R60尺单体，1d8+智力修正穿刺伤害；周围5尺有活体植物时+1d4" },
                { lvl: 1, n: "治愈之芽", c: 1, d: "MP3 | 接触单体，恢复1d8+智力修正HP；对植物型生物效果翻倍" },
                { lvl: 1, n: "纠缠根系", c: 1, d: "MP2 | R30尺，半径10尺范围，力量豁免DC(10+智力修正)否则束缚1轮（无法移动，攻击劣化）；纯石质地面无效" },
                { lvl: 3, n: "毒孢释放", c: 2, d: "MP3 | 以自身为中心半径10尺，持续2轮；范围内每轮体质豁免DC(12+智力修正)，失败受1d6毒素+视觉模糊（攻击-1）；施法者免疫" },
                { lvl: 3, n: "树皮铠甲", c: 2, d: "MP3 | [附赠] 自我增益，防御值+3持续3轮；期间火焰伤害+50%" },
                { lvl: 3, n: "野性变形·初阶", c: 2, d: "MP5 | 变形为中型以下野兽（狼/鹰/豹），持续10分钟；获得该兽形移动方式与感官，物理属性替换（力量/敏捷+2~4），无法施法；HP共享" },
                { lvl: 5, n: "藤鞭风暴", c: 3, d: "MP5 | R30尺，半径20尺范围，2d8+智力修正钝击，敏捷豁免DC(13+智力修正)半伤；无植物环境不可用" },
                { lvl: 5, n: "生命虹吸", c: 3, d: "MP5 | R5尺单体，造成2d8自然伤害，施法者恢复等同伤害50%的HP；对不死伤害翻倍但不回血" },
                { lvl: 5, n: "剧毒灌注", c: 3, d: "MP4 | 接触一把武器，持续3轮；期间每次命中追加1d6毒素，目标体质豁免DC(13+智力修正)否则中毒（每轮1d4毒素，2轮）" },
                { lvl: 7, n: "大地之怒", c: 4, d: "MP8 | R40尺，半径30尺，3d8+智力修正穿刺，敏捷豁免DC(14+智力修正)半伤；区域变为困难地形3轮" },
                { lvl: 7, n: "野性变形·高阶", c: 4, d: "MP10 | 变形为大型野兽或魔兽形态（巨熊/战狼/毒蛇），持续30分钟；物理属性+4~6，获特殊攻击（如巨熊撕咬2d10+力量），获临时HP=等级×2；无法施法；1次/长休" },
                { lvl: 9, n: "林之庇护", c: 5, d: "MP7 | R30尺，半径20尺，持续3轮；范围内友方每轮恢复1d8+智力修正HP，对远程攻击防御+2" },
                { lvl: 9, n: "猛毒之域", c: 5, d: "MP8 | R30尺，半径15尺，持续4轮；范围内每轮体质豁免DC(15+智力修正)，失败受2d8毒素+中毒叠加（已中毒者追加1d8）" },
                { lvl: 9, n: "密林行者", c: 5, d: "[被动] 森林/沼泽/丛林中移速+10尺，施法检定额外+2，困难地形不影响自身；短休时MP恢复翻倍；对植物型魔兽和自然系攻击获得抗性（伤害减半）" },
                { lvl: 11, n: "万木苏醒", c: 6, d: "MP12 | R50尺，唤醒范围内树木（至少3棵），持续3轮；每棵树每轮攻击一名敌人（命中+8，2d10+4钝击），最多控制6棵；密林威力倍增，无树环境不可用" },
                { lvl: 11, n: "完全再生", c: 6, d: "MP10 | 接触单体，持续5轮；每轮自动恢复2d8+智力修正HP，可修复一处非致命肢体损伤（断指/裂骨）；不可恢复完全断肢" },
                { lvl: 11, n: "自然隐匿·高阶", c: 6, d: "[被动·升级] 有植被环境中潜行检定自动优势，察觉DC+8；可在隐匿状态下施放Lv1-Lv3层技能不打破隐身" },
                { lvl: 13, n: "万物归寂", c: 7, d: "MP14 | R40尺，半径40尺；范围内非友方感知豁免DC(16+智力修正)，失败者全属性-3持续3轮+移速减半+再生能力被压制；成功者属性-1持续1轮；对不死/构装无效；1次/长休" },
                { lvl: 13, n: "魔兽共鸣·高阶", c: 7, d: "MP8 | 对三阶以下魔兽建立临时驯服（感知对抗DC15+目标等级），成功后魔兽服从指令1小时；可维持最多2只驯服魔兽同时作战" },
                { lvl: 15, n: "大德鲁伊化身", c: 8, d: "MP18 | 1次/长休，与自然融合化为巨型自然化身（大型，高4米），持续5轮；全属性+4，防御+5，所有自然系技能消耗减半+效果翻倍，免疫毒素/恐惧，每轮自动恢复2d8HP，双重攻击（根拳3d10+力量钝击）；结束后力竭1轮" },
                { lvl: 15, n: "生态领域", c: 8, d: "MP15 | 1次/长休，R50尺展开自然领域持续5轮；领域内：友方每轮恢复智力修正HP，敌方移速减半且攻击检定-2，地面持续生长纠缠植物（进入者力量豁免DC18否则束缚）" },
