        function escapeAttr(s) { return String(s == null ? '' : s).replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

        // 从技能描述中提取 MP 消耗（兼容「MP2 |」「消耗MP4」「MP消耗: 4」「MP：6」等写法）
        // 融合技能树的魔法/神术没有独立 mp 字段，MP 都写在描述里，这里统一兜底解析
        function parseMpCost(desc) {
            if (!desc) return 0;
            var m = String(desc).match(/(?:消耗MP|MP消耗|MP)[:：]?\s*(\d+)/i);
            return m ? (parseInt(m[1], 10) || 0) : 0;
        }

        function getLearnedSkillMap(all) {
            var map = { 技能: {}, 魔法: {}, 神术: {} };
            Object.keys(_.get(all, 'stat_data.主角.资产与能力.角色技能', {})).forEach(function(k) { map.技能[k] = true; });
            Object.keys(_.get(all, 'stat_data.主角.资产与能力.魔法栏', {})).forEach(function(k) { map.魔法[k] = true; });
            Object.keys(_.get(all, 'stat_data.主角.资产与能力.神术栏', {})).forEach(function(k) { map.神术[k] = true; });
            return map;
        }

        // ===== 健壮 JSON 提取（AI 输出常带围栏/尾随说明/多余字符）：优先 fenced，否则按配对括号提取 =====
        function extractJsonArray(text) {
            var raw = String(text == null ? '' : text);
            var cand = null;
            // 1) fenced block
            var fm = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
            if (fm) cand = fm[1];
            else cand = raw;
            // 2) 配对括号提取（跳过字符串内括号，防描述中 ] 干扰）
            var start = cand.indexOf('[');
            if (start === -1) start = cand.indexOf('{');
            if (start !== -1) {
                var opener = cand[start], closer = opener === '[' ? ']' : '}';
                var depth = 0, end = -1;
                for (var i = start; i < cand.length; i++) {
                    var ch = cand[i];
                    if (ch === '"') {
                        i++;
                        while (i < cand.length) {
                            if (cand[i] === '\\') { i += 2; continue; }
                            if (cand[i] === '"') break;
                            i++;
                        }
                    } else if (ch === opener) depth++;
                    else if (ch === closer) { depth--; if (depth === 0) { end = i; break; } }
                }
                if (end !== -1) cand = cand.substring(start, end + 1);
            }
            // 3) 去闭合括号前的尾随逗号 + 行尾分隔符
            cand = cand.replace(/,\s*([\]}])/g, '$1');
            cand = cand.replace(/[,;]+\s*$/g, '');
            // 4) 解析：修复尾随逗号重试；仍失败抛带预览错误
            try { return JSON.parse(cand); }
            catch (e) {
                var fixed = cand.replace(/,\s*([\]}])/g, '$1');
                try { return JSON.parse(fixed); }
                catch (e2) {
                    throw new Error('JSON解析失败：' + e2.message + ' | 原文尾部: …' + cand.slice(-120));
                }
            }
        }
        // 健壮 JSON 对象提取（优先 { ，跳过字符串内的 { } [ ]，供单技能升级等“返回对象”的场景使用）
        function extractJsonObject(text) {
            var raw = String(text == null ? '' : text);
            var cand = null;
            var fm = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
            cand = fm ? fm[1] : raw;
            var start = cand.indexOf('{');
            if (start === -1) return null;
            var depth = 0, end = -1;
            for (var i = start; i < cand.length; i++) {
                var ch = cand[i];
                if (ch === '"') {
                    i++;
                    while (i < cand.length) {
                        if (cand[i] === '\\') { i += 2; continue; }
                        if (cand[i] === '"') break;
                        i++;
                    }
                } else if (ch === '{') depth++;
                else if (ch === '}') { depth--; if (depth === 0) { end = i; break; } }
            }
            if (end === -1) return null;
            cand = cand.substring(start, end + 1);
            cand = cand.replace(/,\s*([\]}])/g, '$1');
            try { return JSON.parse(cand); }
            catch (e) { return null; }
        }

        /* ================= 自创职业检测与定制技能树（AI 生成 1-20 级技能树） ================= */
