                _.set(stat2, '$customSkillTrees', trees);
                // 同步写入所有持有该职业的角色的职业信息条（展示用；升级脚本以 $customSkillTrees 中的风格为准）
                ['主角'].concat(Object.keys(stat2.同伴 || {})).concat(Object.keys(stat2.契约兽 || {})).forEach(function (tKey) {
