            var j = jobName || '';
            if (/神官|圣殿骑士|祭司/.test(j)) return '神术';
            if (/^MP\d|^MP\s|施法|术式|魔法/.test(d)) return '魔法';
            return '技能';
        }
        function skillSlotKeyOf(type) { return type === '魔法' ? '魔法栏' : (type === '神术' ? '神术栏' : '角色技能'); }

        /* ============ 元素法师流派（职业名后缀「元素法师（水、火）」→ 技能树按流派过滤） ============ */
        var ELEM_KEYWORDS = {
            '火': ['火', '焰', '燃', '炽热', '陨石', '焚天', '不灭', '焦土', '熔岩', '炎柱', '烬'],
            '水': ['水', '涟漪', '潮汐', '深海', '海啸', '万流', '大漩涡', '深渊漩涡'],
            '风': ['风刃', '气旋', '轻身术', '龙卷', '大气', '风暴', '飓风', '万象风', '天空', '真空', '风行者'],
            '土': ['岩弹', '岩壁', '石', '大地', '磐石', '地壳', '石化', '晶化', '地震', '沙尘', '地刺', '吞噬'],
            '雷': ['电击', '静电', '电磁', '闪电', '雷光', '雷击', '雷暴', '超载', '天罚', '迅雷', '雷神', '永劫', '雷霆', '磁暴'],
            '冰': ['冰', '霜', '寒冰', '冻结', '冻土', '凛', '冰川', '严寒', '冰棺', '冰锥', '绝对零度', '永恒冰', '永冻', '极寒']
        };
        // 检测技能所属元素（可多元素，如融合技）；空数组 = 无元素通用
        function detectSkillElements(sk) {
            var text = (sk.n || '') + ' ' + (sk.d || '');
            var found = [];
            for (var elem in ELEM_KEYWORDS) {
                for (var i = 0; i < ELEM_KEYWORDS[elem].length; i++) {
                    if (text.indexOf(ELEM_KEYWORDS[elem][i]) !== -1) { found.push(elem); break; }
                }
            }
            return found;
        }
        // 解析职业名后缀（元素法师流派）：
        //   括号（兼容旧档）：元素法师（水、火）→ { base:'元素法师', elements:['水','火'] }
        //   点号（现行规范）：元素法师·水 / 元素法师·水·火  → base + elements（元素法师家族一律用「·」分隔流派）
        function jobElemFilter(jobName) {
            var s = String(jobName || '');
            var m = s.match(/^(.*?)（([^）]*)）$/);
            if (m) { var e = m[2].split(/[、,，\s]+/).filter(Boolean); return { base: m[1].trim(), elements: e.length ? e : null }; }
            var families = ['元素法师', '符文师', '塑能师', '死灵法师', '召唤师', '魔导技师', '精灵术士', '药剂师', '圣光法师', '邪术师'];
            var m2 = s.split('·');
            if (m2.length >= 2 && families.indexOf(m2[0].trim()) !== -1) {
                return { base: m2[0].trim(), elements: m2.slice(1).map(function(x) { return x.trim(); }).filter(Boolean) };
            }
            return { base: s, elements: null };
        }
        // 该技能是否被职业后缀允许（无后缀→全允许；无元素通用→允许；有元素→需与后缀有交集）
        function jobSkillAllowed(jobName, sk) {
            var f = jobElemFilter(jobName);
            if (!f.elements) return true;
            var es = detectSkillElements(sk);
            if (!es.length) return true;
            return es.some(function(e) { return f.elements.indexOf(e) !== -1; });
        }

        function renderSkillTree() {
            var $container = $('#list-skilltree');
            if (!$container || !$container.length) return;
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var jobInfo = _.get(all, 'stat_data.主角.基础状态.职业信息', {});
            var trees = _.get(all, 'stat_data.$customSkillTrees', {});
            var learned = getLearnedSkillMap(all);
            var jobNames = Object.keys(jobInfo);
            if (!jobNames.length) { $container.html('<div class="jrpg-list-empty">暂无职业，无职业技能树</div>'); return; }
            var totalSp = 0;
            jobNames.forEach(function(job) { totalSp += parseInt(jobInfo[job].技能点 || 0, 10) || 0; });
            var html = '<div style="font-size:12px;color:#6b4e31;margin-bottom:8px;padding:6px 10px;background:rgba(139,107,74,0.1);border-radius:4px;line-height:1.6;">';
            html += '📌 可用技能点：<strong style="color:#d35400;">' + totalSp + '</strong> 点';
            html += '<div style="font-size:10px;color:#7f8c8d;margin-top:2px;">职业技能树（1-20级）。学习消耗「技能点」；未达职业等级或技能点不足时不可学。</div></div>';
            jobNames.forEach(function(jobName) {
                var jobLv = parseInt(jobInfo[jobName].等级 || 1, 10) || 1;
                var jf = jobElemFilter(jobName);
                // 融合职业技能树：职业融合保存时写入 $customSkillTrees[融合职业名]['职业融合'].skills，优先显示
                var fuseDef = (trees[jobName] && trees[jobName]['职业融合']) || null;
                var fuseSkills = (fuseDef && Array.isArray(fuseDef.skills) && fuseDef.skills.length) ? fuseDef.skills : null;
                var isFuse = !!fuseSkills;
                // 自创职业定制技能树：AI 生成后写入 $customSkillTrees[职业名]['定制技能树'].skills
                var customDef = (trees[jobName] && trees[jobName]['定制技能树']) || null;
                var customSkills = (customDef && Array.isArray(customDef.skills) && customDef.skills.length) ? customDef.skills : null;
                var isCustom = !!customSkills;
                var skills = fuseSkills || customSkills || ((typeof dbSkills !== 'undefined' && dbSkills[jf.base]) || []);
                // 元素流派过滤（如「元素法师（水）」只显示 水/无元素通用 技能；融合技能无元素则全通过）
                var filtered = skills.filter(function(sk) { return jobSkillAllowed(jobName, sk); });
                var elemBadge = (jf.elements && jf.elements.length) ? ' <span style="font-size:10px;color:#2980b9;font-weight:normal;">流派：' + escapeAttr(jf.elements.join('·')) + '</span>' : '';
                var fuseBadge = isFuse ? ' <span style="font-size:10px;color:#8e44ad;font-weight:normal;">🔀 融合技能树</span>' : '';
                var customBadge = isCustom ? ' <span style="font-size:10px;color:#8e44ad;font-weight:normal;">🎨 定制技能树</span>' : (isOfficialJob(jobName) ? '' : ' <span style="font-size:10px;color:#c0392b;font-weight:normal;">⚠️ 自创职业</span>');
                html += '<div class="jrpg-skilltree-job" data-job="' + escapeAttr(jobName) + '">';
                html += '<div class="jrpg-skilltree-head" style="font-weight:bold;color:#6b2e2e;margin:10px 0 4px 0;border-bottom:2px solid #8b6b4a;background:rgba(139,107,74,0.08);padding:4px 8px;border-radius:4px;cursor:pointer;user-select:none;" title="点击折叠/展开">⚔️ ' + escapeAttr(jobName) + ' <span style="font-size:11px;color:#8b6b4a;font-weight:normal;">Lv.' + jobLv + ' · ' + filtered.length + ' 技能</span>' + fuseBadge + customBadge + elemBadge + ' <span class="jrpg-skilltree-arrow" style="float:right;color:#8b6b4a;">▾</span></div>';
                html += '<div class="jrpg-skilltree-body" style="max-height:320px;overflow-y:auto;">';
                if (!filtered.length) {
                    if (!isOfficialJob(jobName)) {
                        // 自创职业且尚未生成定制技能树：提示并提供 AI 生成入口（已选「永不检测」则只提示不打扰）
                        var neverMap = _.get(all, 'stat_data.$flags.自创职业永不检测', {});
                        if (neverMap[jobName]) {
                            html += '<div class="jrpg-list-empty" style="color:#7f8c8d;">🚫 自创职业「' + escapeAttr(jobName) + '」已选择「永不检测」，未生成定制技能树。如需生成，请点击右上角全局修改器清除 $flags.自创职业永不检测 中的该项。</div>';
                        } else {
                            html += '<div class="jrpg-list-empty" style="color:#c0392b;">⚠️ 检测到自创职业「' + escapeAttr(jobName) + '」：不在官方职业技能树中。可点击下方按钮，用 AI（generateRaw）为其生成一套 1-20 级定制技能树。</div>';
                            html += '<div style="margin-top:8px;"><button class="jrpg-btn-sm jrpg-csgen" data-job="' + escapeAttr(jobName) + '" style="background:#8e44ad;color:#fff;border:2px solid #8e44ad;border-radius:4px;padding:6px 14px;font-size:12px;cursor:pointer;">🤖 生成定制技能树（1-20级）</button></div>';
                        }
                    } else {
                        html += '<div class="jrpg-list-empty">' + (isFuse ? '该融合职业暂无技能数据' : '该职业暂无可用技能（受流派限制）') + '</div>';
                    }
                } else {
                // 等级段模板分组（对齐位阶：1-4普通/5-8超凡/9-12精英/13-16史诗/17-20传说/21+神话），每段可折叠；默认仅展开当前位阶所在段
                var BANDS = [
                    { min: 1, max: 4, name: '普通阶' },
                    { min: 5, max: 8, name: '超凡阶' },
                    { min: 9, max: 12, name: '精英阶' },
                    { min: 13, max: 16, name: '史诗阶' },
                    { min: 17, max: 20, name: '传说阶' },
                    { min: 21, max: 999, name: '神话阶' }
                ];
                var byLv = {};
                filtered.forEach(function(sk) { var lv = sk.lvl || 1; (byLv[lv] = byLv[lv] || []).push(sk); });
                var lvKeys = Object.keys(byLv).map(Number).sort(function(a, b) { return a - b; });
                var bandIdBase = jobName.replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                var bandSections = [];
                BANDS.forEach(function(band, bi) {
                    var lvs = lvKeys.filter(function(lv) { return lv >= band.min && lv <= band.max; });
                    if (!lvs.length) return;
                    var bandSkills = lvs.reduce(function(arr, lv) { return arr.concat(byLv[lv]); }, []);
                    var learnedCount = bandSkills.filter(function(sk) {
                        var t = (isFuse && sk.type) ? sk.type : skillTypeOf(sk, jobName);
                        return !!(learned[t] && learned[t][sk.n]);
                    }).length;
                    var isCurrent = jobLv >= band.min && jobLv <= band.max;
                    bandSections.push({ band: band, lvs: lvs, count: bandSkills.length, learnedCount: learnedCount, isCurrent: isCurrent });
                });
                if (bandSections.length && !bandSections.some(function(s) { return s.isCurrent; })) {
                    // 角色等级超出全部已解锁段（如高等级低阶树）：展开最后一段兜底
                    bandSections[bandSections.length - 1].isCurrent = true;
                }
                bandSections.forEach(function(sec) {
                    var bandId = 'lvband-' + bandIdBase + '-' + sec.band.min;
                    var open = (window.__isuriaFoldState && window.__isuriaFoldState['#' + bandId] !== undefined) ? window.__isuriaFoldState['#' + bandId] : sec.isCurrent;
                    html += '<div style="font-weight:bold;color:#5a4430;margin:8px 0 0;font-size:12px;background:rgba(139,107,74,0.1);border-radius:4px;padding:4px 8px;cursor:pointer;user-select:none;" data-fold-target="#' + bandId + '" title="点击折叠/展开">';
                    html += '📚 ' + sec.band.name + ' <span style="font-size:10px;color:#8b6b4a;font-weight:normal;">Lv.' + sec.band.min + (sec.band.max <= 20 ? '-' + sec.band.max : '+') + ' · ' + sec.count + ' 技能' + (sec.learnedCount ? ' · 已学 ' + sec.learnedCount : '') + '</span>' + (sec.isCurrent ? ' <span style="font-size:10px;color:#27ae60;font-weight:normal;">📍当前</span>' : '');
                    html += '<span class="jrpg-fold-arrow" style="float:right;color:#8b6b4a;">' + (sec.isCurrent ? '▾' : '▸') + '</span></div>';
                    html += '<div id="' + bandId + '" style="display:' + (sec.isCurrent ? '' : 'none') + ';">';
                    sec.lvs.forEach(function(lv) {
                        var locked = jobLv < lv;
                        html += '<div style="font-weight:bold;color:' + (locked ? '#aaa' : '#8b6b4a') + ';margin:8px 0 2px;font-size:12px;border-bottom:1px dashed #d2b48c;">Lv.' + lv + (locked ? ' <span style="color:#e74c3c;font-size:10px;font-weight:normal;">🔒 需' + escapeAttr(jobName) + ' ' + lv + '级</span>' : '') + '</div>';
                        byLv[lv].forEach(function(sk) {
                            // 融合技能自带 type；普通技能用描述前缀推断
                            var type = (isFuse && sk.type) ? sk.type : skillTypeOf(sk, jobName);
                            var skillName = sk.n || '';
                            if (!skillName) return;
                            var typeIcon = type === '魔法' ? '✦' : (type === '神术' ? '✧' : '⚔️');
                            var isLearned = !!(learned[type] && learned[type][skillName]);
                            var cost = parseInt(sk.c, 10) || 1;
                            var spNotEnough = cost > totalSp;
                            html += '<div class="jrpg-list-item" style="' + (isLearned ? 'opacity:0.75;' : (locked || spNotEnough ? 'opacity:0.55;' : '')) + '">';
                            html += '<div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(skillName) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + type + ']</span></span>';
                            if (isLearned) html += '<span style="color:#27ae60;font-size:11px;font-weight:bold;">✅ 已学习</span>';
                            else if (locked) html += '<span style="color:#e74c3c;font-size:11px;">🔒 需 ' + lv + '级</span>';
                            else if (spNotEnough) html += '<button class="jrpg-btn-sm" disabled style="background:#bbb;color:#fff;border-color:#bbb;padding:2px 10px;font-size:11px;cursor:not-allowed;" title="需要 ' + cost + ' 点技能点，当前可用 ' + totalSp + ' 点">技能点不足</button>';
                            else html += '<button class="jrpg-btn-sm ' + (isFuse ? 'jrpg-vs-learn' : 'jrpg-st-learn') + '" data-job="' + escapeAttr(jobName) + '" data-skill="' + escapeAttr(skillName) + '" data-type="' + type + '" style="background:#2980b9;color:#fff;border-color:#2980b9;padding:2px 10px;font-size:11px;">学习 (-' + cost + '点)</button>';
                            html += '</div>';
                            html += '<div class="jrpg-item-desc">' + escapeAttr(sk.d || '') + (isFuse && sk.lvl ? '　<span style="color:#e74c3c;">[需融合 Lv.' + sk.lvl + ']</span>' : '') + '</div>';
                            html += '</div>';
                        });
                    });
                    html += '</div>';
                });
                }
                html += '</div>';
                html += '</div>';
            });
            $container.html(html);
        }

        // 学习职业技能：从 dbSkills 取定义，校验职业等级与技能点，写入对应技能栏
        async function learnSkillTreeSkill(jobName, skillName, type) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var jobInfo = _.get(stat, '主角.基础状态.职业信息', {});
                var jf = jobElemFilter(jobName);
                var skDef = null;
                // 先查自定义技能树（$customSkillTrees[职业]），再查内置技能库（dbSkills）
                var cst = _.get(stat, '$customSkillTrees', {});
                Object.keys(cst).forEach(function (cj) {
                    var cBase = (typeof jobElemFilter === 'function') ? jobElemFilter(cj).base : cj;
                    if (cBase !== jf.base && cj !== jobName) return;
                    var vMap = cst[cj] || {};
                    Object.keys(vMap).forEach(function (vn) {
                        var vData = vMap[vn] || {};
                        (vData.skills || []).forEach(function (sk) { if (sk && sk.n === skillName && !skDef) skDef = sk; });
                    });
                });
                if (!skDef) {
                    ((typeof dbSkills !== 'undefined' && dbSkills[jf.base]) || []).forEach(function (sk) { if (sk.n === skillName) skDef = sk; });
                }
                if (!skDef) { if (window.toastr) toastr.error('未找到职业技能「' + skillName + '」的定义'); return; }
                // 元素流派校验（如「元素法师（水）」只允许 水/无元素通用 技能）
                if (!jobSkillAllowed(jobName, skDef)) {
                    var es2 = detectSkillElements(skDef);
                    if (window.toastr) toastr.error('「' + skillName + '」属于[' + (es2.join('、') || '无元素') + ']流派，不在当前职业（' + jobName + '）允许的流派内');
                    return;
                }
                // 校验职业等级
                var jobLv = parseInt(jobInfo[jobName] && jobInfo[jobName].等级, 10) || 1;
                if (jobLv < (skDef.lvl || 1)) { if (window.toastr) toastr.error('需 ' + jobName + ' Lv.' + skDef.lvl + ' 才能学习'); return; }
                var cost = parseInt(skDef.c, 10) || 1;
                var slotKey = skillSlotKeyOf(type);
                var slot = _.get(stat, '主角.资产与能力.' + slotKey, {});
                if (slot[skillName]) { if (window.toastr) toastr.warning('已掌握「' + skillName + '」，无需重复学习'); return; }
                // 技能点：优先扣该职业技能点，不足扣其它职业
                var realJob = jobInfo[jobName] ? jobName : null;
                if (!realJob) { Object.keys(jobInfo).forEach(function(k) { if (!realJob && (k.indexOf(jobName) !== -1 || jobName.indexOf(k) !== -1)) realJob = k; }); }
                var totalJobSp = 0;
                Object.keys(jobInfo).forEach(function(k) { totalJobSp += parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0; });
                if (totalJobSp < cost) { if (window.toastr) toastr.error('技能点不足！学习「' + skillName + '」需要 ' + cost + ' 点，当前可用 ' + totalJobSp + ' 点'); return; }
                var jobSp = realJob ? (parseInt(_.get(jobInfo, [realJob, '技能点'], 0), 10) || 0) : 0;
                if (jobSp >= cost) { _.set(jobInfo, [realJob || jobName, '技能点'], jobSp - cost); }
                else {
                    var remain = cost;
                    if (realJob) { _.set(jobInfo, [realJob, '技能点'], 0); remain -= jobSp; }
                    Object.keys(jobInfo).forEach(function(k) {
                        if (remain <= 0) return;
                        var sp = parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0;
                        if (sp > 0) { var take = Math.min(sp, remain); _.set(jobInfo, [k, '技能点'], sp - take); remain -= take; }
                    });
                }
                var entry = { 描述: skDef.d || '', 等级: 1 };
                if (type !== '技能') {
                    entry.消耗MP = parseInt(skDef.mp, 10) || parseMpCost(skDef.d) || 0;
                }
                slot[skillName] = entry;
                _.set(stat, '主角.资产与能力.' + slotKey, slot);
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                // 上下文注入「技能学习」通知（不产生楼层，下一次生成生效）
                try { await emitAllocPrompt('【技能学习】' + jobName + ' 学习了职业技能「' + skillName + '」（消耗技能点 -' + cost + '）。该技能已写入技能栏，请勿重复学习或修改。', 'skill_'); } catch (e) { console.error('注入技能学习通知失败:', e); }
                if (window.toastr) toastr.success('✅ 已学习「' + skillName + '」！');
                populateCharacterData();
            } catch (e) {
                console.error('学习职业技能失败:', e);
                if (window.toastr) toastr.error('学习失败：' + (e && e.message ? e.message : e));
            }
        }

        function renderVariantSkills() {
            var $container = $('#list-variant-skills');
            if (!$container || !$container.length) return;
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var trees = _.get(all, 'stat_data.$customSkillTrees', {});
            var learned = getLearnedSkillMap(all);
            var jobInfo = _.get(all, 'stat_data.主角.基础状态.职业信息', {});
            // 同伴专属技能树（顶层键为同伴名）不在主角变体技能 tab 渲染
            var compNames = Object.keys(_.get(all, 'stat_data.同伴', {}));

            var filteredTrees = {};
            Object.keys(trees).forEach(function(k) { if (compNames.indexOf(k) === -1) filteredTrees[k] = trees[k]; });
            trees = filteredTrees;

            if (!trees || Object.keys(trees).length === 0) {
                $container.html('<div class="jrpg-list-empty">暂无变体技能树。请先在「角色创建」页生成并保存变体技能树。</div>');
                return;
            }

            var totalSp = 0;
            Object.keys(jobInfo).forEach(function(job) { totalSp += parseInt(jobInfo[job].技能点 || 0, 10) || 0; });

            var html = '<div style="font-size:12px;color:#6b4e31;margin-bottom:8px;padding:6px 10px;background:rgba(139,107,74,0.1);border-radius:4px;line-height:1.6;">';
            html += '📌 可用技能点：<strong style="color:#d35400;">' + totalSp + '</strong> 点';
            html += '<div style="font-size:10px;color:#7f8c8d;margin-top:2px;">学习消耗「技能点」；技能点不足时按钮会置灰不可点。</div></div>';

            Object.keys(trees).forEach(function(jobName) {
                var vMap = trees[jobName] || {};
                Object.keys(vMap).forEach(function(variantName) {
                    var vData = vMap[variantName] || {};
                    var skills = vData.skills || [];
                    if (!skills.length) return;
                    var fuseLv = parseInt(vData.level, 10) || 0;
                    html += '<div style="font-weight:bold;color:#8e44ad;margin:10px 0 4px 0;border-bottom:2px solid #8e44ad;background:rgba(142,68,173,0.06);padding:4px 8px;border-radius:4px;">🎨 ' + escapeAttr(jobName) + ' · ' + escapeAttr(variantName) + (fuseLv ? ' <span style="font-size:10px;color:#8e44ad;">继承Lv.' + fuseLv + '</span>' : '') + '</div>';
                    // 等级段模板折叠（与职业技能树同款）
                    var VBANDS = [
                        { min: 1, max: 4, name: '普通阶' },
                        { min: 5, max: 8, name: '超凡阶' },
                        { min: 9, max: 12, name: '精英阶' },
                        { min: 13, max: 16, name: '史诗阶' },
                        { min: 17, max: 20, name: '传说阶' },
                        { min: 21, max: 999, name: '神话阶' }
                    ];
                    function vType(sk) { var t = sk.type || '技能'; return t === '魔法' ? '魔法' : (t === '神术' ? '神术' : '技能'); }
                    function vLearned(sk) {
                        var typeName = vType(sk);
                        var skillName = sk.n || '';
                        if (!learned[typeName]) return false;
                        if (learned[typeName][skillName]) return true;
                        var hit = false;
                        Object.keys(learned[typeName]).forEach(function(learnedKey) {
                            if (!hit && (learnedKey === skillName || learnedKey.indexOf('] ' + skillName) !== -1 || learnedKey.indexOf('「' + skillName + '」') !== -1)) hit = true;
                        });
                        return hit;
                    }
                    var vByLv = {};
                    skills.forEach(function(sk) { var lv = sk.lvl || 1; (vByLv[lv] = vByLv[lv] || []).push(sk); });
                    var vLvKeys = Object.keys(vByLv).map(Number).sort(function(a, b) { return a - b; });
                    var vBandIdBase = (jobName + '-' + variantName).replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                    var vSections = [];
                    VBANDS.forEach(function(band) {
                        var lvs = vLvKeys.filter(function(lv) { return lv >= band.min && lv <= band.max; });
                        if (!lvs.length) return;
                        var bandSkills = lvs.reduce(function(arr, lv) { return arr.concat(vByLv[lv]); }, []);
                        var learnedCount = bandSkills.filter(function(sk) { return sk.n && vLearned(sk); }).length;
                        vSections.push({ band: band, lvs: lvs, count: bandSkills.length, learnedCount: learnedCount });
                    });
                    // 默认展开：第一个含「未学习且未锁等级」技能的段；全学完则展开最后一段
                    var openIdx = -1;
                    vSections.forEach(function(sec, si) {
                        if (openIdx !== -1) return;
                        var hasTarget = sec.lvs.some(function(lv) {
                            return vByLv[lv].some(function(sk) {
                                var locked = fuseLv > 0 && sk.lvl && (parseInt(sk.lvl, 10) > fuseLv);
                                return sk.n && !vLearned(sk) && !locked;
                            });
                        });
                        if (hasTarget) openIdx = si;
                    });
                    if (openIdx === -1 && vSections.length) openIdx = vSections.length - 1;
                    vSections.forEach(function(sec, si) {
                        var bandId = 'vband-' + vBandIdBase + '-' + sec.band.min;
                        var open = (window.__isuriaFoldState && window.__isuriaFoldState['#' + bandId] !== undefined) ? window.__isuriaFoldState['#' + bandId] : (si === openIdx);
                        html += '<div style="font-weight:bold;color:#5a4430;margin:8px 0 0;font-size:12px;background:rgba(142,68,173,0.08);border-radius:4px;padding:4px 8px;cursor:pointer;user-select:none;" data-fold-target="#' + bandId + '" title="点击折叠/展开">';
                        html += '📚 ' + sec.band.name + ' <span style="font-size:10px;color:#8b6b4a;font-weight:normal;">Lv.' + sec.band.min + (sec.band.max <= 20 ? '-' + sec.band.max : '+') + ' · ' + sec.count + ' 技能' + (sec.learnedCount ? ' · 已学 ' + sec.learnedCount : '') + '</span>';
                        html += '<span class="jrpg-fold-arrow" style="float:right;color:#8b6b4a;">' + (open ? '▾' : '▸') + '</span></div>';
                        html += '<div id="' + bandId + '" style="display:' + (open ? '' : 'none') + ';">';
                        sec.lvs.forEach(function(lv) {
                            html += '<div style="font-weight:bold;color:#8b6b4a;margin:8px 0 2px;font-size:12px;border-bottom:1px dashed #d2b48c;">Lv.' + lv + '</div>';
                            vByLv[lv].forEach(function(sk) {
                                var typeName = vType(sk);
                                var skillName = sk.n || '';
                                if (!skillName) return;
                                var typeIcon = typeName === '魔法' ? '✦' : (typeName === '神术' ? '✧' : '⚔️');
                                var isLearned = vLearned(sk);
                                var cost = parseInt(sk.c, 10) || 1;
                                var lvlLocked = fuseLv > 0 && sk.lvl && (parseInt(sk.lvl, 10) > fuseLv);
                                var spNotEnough = cost > totalSp;
                                html += '<div class="jrpg-list-item" style="' + (isLearned ? 'opacity:0.75;' : ((lvlLocked || spNotEnough) ? 'opacity:0.55;' : '')) + '">';
                                html += '<div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(skillName) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + typeName + ']</span></span>';
                                if (isLearned) {
                                    html += '<span style="color:#27ae60;font-size:11px;font-weight:bold;">✅ 已学习</span>';
                                } else if (lvlLocked) {
                                    html += '<span style="color:#e74c3c;font-size:11px;font-weight:bold;">🔒 需融合 Lv.' + sk.lvl + '</span>';
                                } else if (spNotEnough) {
                                    html += '<button class="jrpg-btn-sm" disabled style="background:#bbb;color:#fff;border-color:#bbb;padding:2px 10px;font-size:11px;cursor:not-allowed;" title="需要 ' + cost + ' 点技能点，当前可用 ' + totalSp + ' 点">技能点不足</button>';
                                } else {
                                    html += '<button class="jrpg-btn-sm jrpg-vs-learn" data-job="' + escapeAttr(jobName) + '" data-skill="' + escapeAttr(skillName) + '" data-type="' + typeName + '" style="background:#2980b9;color:#fff;border-color:#2980b9;padding:2px 10px;font-size:11px;">学习 (-' + cost + '点)</button>';
                                }
                                html += '</div>';
                                html += '<div class="jrpg-item-desc">' + escapeAttr(sk.d || '') + (sk.lvl ? '　<span style="color:#e74c3c;">[需' + (fuseLv > 0 ? '融合' : escapeAttr(jobName)) + ' Lv.' + sk.lvl + ']</span>' : '') + '</div>';
                                html += '</div>';
                            });
                        });
                        html += '</div>';
                    });
                });
            });
            $container.html(html);
        }

        async function learnVariantSkill(jobName, skillName, type) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var trees = _.get(stat, '$customSkillTrees', {});

                var skDef = null;
                Object.keys(trees[jobName] || {}).forEach(function(vn) {
                    (trees[jobName][vn].skills || []).forEach(function(sk) {
                        if (sk.n === skillName) skDef = sk;
                    });
                });
                if (!skDef) { if (window.toastr) toastr.error('未找到变体技能「' + skillName + '」的定义'); return; }
                var cost = parseInt(skDef.c, 10) || 1;

                var slotKey = type === '魔法' ? '魔法栏' : (type === '神术' ? '神术栏' : '角色技能');
                var slot = _.get(stat, '主角.资产与能力.' + slotKey, {});
                if (slot[skillName]) { if (window.toastr) toastr.warning('已掌握「' + skillName + '」，无需重复学习'); return; }

                // 定位职业技能点（兼容职业信息键名与变体技能树职业名不一致的情况）
                var jobInfo = _.get(stat, '主角.基础状态.职业信息', {});
                var realJob = null;
                if (jobInfo[jobName]) realJob = jobName;
                else {
                    Object.keys(jobInfo).forEach(function(k) {
                        if (!realJob && (k.indexOf(jobName) !== -1 || jobName.indexOf(k) !== -1)) realJob = k;
                    });
                }
                // 汇总所有职业技能点作为可用技能点（学习只消耗「技能点」，与 SP 条无关）
                var totalJobSp = 0;
                Object.keys(jobInfo).forEach(function(k) { totalJobSp += (parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0); });
                var jobSp = realJob ? (parseInt(_.get(jobInfo, [realJob, '技能点'], 0), 10) || 0) : 0;
                if (totalJobSp < cost) {
                    if (window.toastr) toastr.error('技能点不足！学习「' + skillName + '」需要 ' + cost + ' 点技能点，当前可用技能点 ' + totalJobSp);
                    return;
                }

                // 优先扣对应职业技能点，不足再扣其它职业技能点
                if (jobSp >= cost) {
                    _.set(jobInfo, [realJob || jobName, '技能点'], jobSp - cost);
                } else {
                    var remain = cost;
                    if (realJob) { _.set(jobInfo, [realJob, '技能点'], 0); remain -= jobSp; }
                    Object.keys(jobInfo).forEach(function(k) {
                        if (remain <= 0) return;
                        var sp = parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0;
                        if (sp > 0) {
                            var take = Math.min(sp, remain);
                            _.set(jobInfo, [k, '技能点'], sp - take);
                            remain -= take;
                        }
                    });
                }
                var entry = { 描述: skDef.d || '', 等级: 1 };
                if (type !== '技能') entry.消耗MP = parseInt(skDef.mp, 10) || parseMpCost(skDef.d) || 0;
                slot[skillName] = entry;
                _.set(stat, '主角.资产与能力.' + slotKey, slot);

                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });

                // 上下文注入「技能学习」通知（不产生楼层，下一次生成生效）
                try { await emitAllocPrompt('【技能学习】' + jobName + ' 学习了变体技能「' + skillName + '」（消耗技能点 -' + cost + '）。该技能已写入技能栏，请勿重复学习或修改。', 'skill_'); } catch (e) { console.error('注入技能学习通知失败:', e); }

                if (window.toastr) toastr.success('✅ 已学习「' + skillName + '」！');
                populateCharacterData();
            } catch (e) {
                console.error('学习变体技能失败:', e);
                if (window.toastr) toastr.error('学习失败：' + (e && e.message ? e.message : e));
            }
        }

