            // 已有技能树展示 + 逐级学习
            var trees = _.get(stat, '$customSkillTrees', {});
            var tree = (trees[companionSkillTarget] && trees[companionSkillTarget]['专属技能树']) || null;
            var skills = (tree && tree.skills) || [];
            if (skills.length) {
                html += '<div style="font-weight:bold;color:#8e44ad;margin:12px 0 4px 0;border-bottom:2px solid #8e44ad;background:rgba(142,68,173,0.06);padding:4px 8px;border-radius:4px;">🎨 ' + escapeAttr(companionSkillTarget) + ' 的专属技能树（' + skills.length + ' 技能，逐级解锁）</div>';
                var jobInfo = _.get(c, '基础状态.职业信息', {});
                var totalSp = 0, maxJobLv = 1;
                Object.keys(jobInfo).forEach(function(j) { totalSp += parseInt(jobInfo[j].技能点 || 0, 10) || 0; maxJobLv = Math.max(maxJobLv, parseInt(jobInfo[j].等级 || 1, 10) || 1); });
                var learned = allocLearned(c, companionSkillTarget);
                skills.forEach(function(sk) {
                    var type = sk.type || '技能';
                    var skillName = sk.n || '';
                    if (!skillName) return;
