            var promptText = '你正在为一位同伴生成专属技能树。以下信息完全来自该同伴的角色变量，请只依据这些信息生成，不要参考其他任何上下文。\n\n';
            promptText += '【同伴基本信息】\n';
            promptText += '名字：' + companionName + '\n';
            promptText += '等阶：' + (c.等阶 || '普通') + '\n';
            promptText += '种族：' + (c.种族 || '未知') + '\n';
            promptText += '身份：' + (c.身份 || '未知') + '\n';
            promptText += '外貌：' + (c.外貌 || '') + '\n';
            promptText += '性格：' + (c.性格 || '') + '\n';
