                var trees = _.get(stat2, '$customSkillTrees', {});
                if (!trees[companionName]) trees[companionName] = {};
                trees[companionName]['专属技能树'] = { skills: validSkills, level: 0 };
                _.set(stat2, '$customSkillTrees', trees);
                // 替换同伴整体技能树：清空原已学技能，让玩家按新技能树逐级重新学习
