        async function learnCompanionSkill(companionName, skillName, type) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = mvuData.stat_data || (mvuData.stat_data = {});
                var trees = _.get(stat, '$customSkillTrees', {});
                var tree = (trees[companionName] && trees[companionName]['专属技能树']) || null;
                if (!tree) { if (window.toastr) toastr.error('未找到「' + companionName + '」的专属技能树'); return; }
                var skDef = null;
                (tree.skills || []).forEach(function(sk) { if (sk.n === skillName) skDef = sk; });
                if (!skDef) { if (window.toastr) toastr.error('未找到技能「' + skillName + '」的定义'); return; }
                var actor = _.get(stat, ['同伴', companionName], null);
                if (!actor) { if (window.toastr) toastr.error('未找到同伴「' + companionName + '」数据'); return; }
                var jobInfo = _.get(actor, '基础状态.职业信息', {});
                var maxJobLv = 1;
                Object.keys(jobInfo).forEach(function(j) { maxJobLv = Math.max(maxJobLv, parseInt(jobInfo[j].等级 || 1, 10) || 1); });
                var lvl = parseInt(skDef.lvl, 10) || 1;
                if (maxJobLv < lvl) { if (window.toastr) toastr.error('「' + companionName + '」职业等级不足：该技能需职业 Lv.' + lvl + '，当前最高 Lv.' + maxJobLv); return; }
                var cost = parseInt(skDef.c, 10) || 1;
                var totalSp = 0;
                Object.keys(jobInfo).forEach(function(j) { totalSp += parseInt(jobInfo[j].技能点 || 0, 10) || 0; });
                if (totalSp < cost) { if (window.toastr) toastr.error('技能点不足！学习「' + skillName + '」需要 ' + cost + ' 点，当前可用 ' + totalSp + ' 点'); return; }
                var skills = actor.技能 || (actor.技能 = {});
                if (skills[skillName]) { if (window.toastr) toastr.warning('该同伴已掌握「' + skillName + '」，无需重复学习'); return; }
                // 扣技能点（优先扣最高等级职业，不足再扣其它）
                var remain = cost;
                var ordered = Object.keys(jobInfo).sort(function(a, b) { return (parseInt(jobInfo[b].等级, 10) || 0) - (parseInt(jobInfo[a].等级, 10) || 0); });
                ordered.forEach(function(j) {
                    if (remain <= 0) return;
                    var sp = parseInt(jobInfo[j].技能点 || 0, 10) || 0;
                    if (sp > 0) { var take = Math.min(sp, remain); jobInfo[j].技能点 = sp - take; remain -= take; }
                });
                if (remain > 0) { if (window.toastr) toastr.error('技能点不足！'); return; }
                var entry = { 描述: skDef.d || '', 等级: 1 };
                if (type !== '技能') entry.消耗MP = parseInt(skDef.mp, 10) || parseMpCost(skDef.d) || 0;
                skills[skillName] = entry;
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                try { await emitAllocPrompt('【技能学习】同伴「' + companionName + '」学习了专属技能「' + skillName + '」（需职业 Lv.' + lvl + '，消耗技能点 -' + cost + '）。该技能已写入该同伴技能栏，请勿重复学习或修改。', 'skill_'); } catch (e) { console.error('注入技能学习通知失败:', e); }
                if (window.toastr) toastr.success('✅ 已为「' + companionName + '」学习「' + skillName + '」！');
                renderCompanionSkillTree();
                populateCharacterData();
            } catch (e) {
                console.error('学习同伴专属技能失败:', e);
                if (window.toastr) toastr.error('学习失败：' + (e && e.message ? e.message : e));
            }
        }

        /* ================= � 职业融合（AI 生成融合技能树，继承两职业等级） ================= */
