                    if (check.ok) {
                        html += '<button class="jrpg-do-jobchange" data-target="' + escapeAttr(target) + '" data-job="' + escapeAttr(job) + '" style="padding:3px 10px;border:1px solid #1f7a4a;background:rgba(31,122,74,.12);color:#1f6a3a;border-radius:3px;font-size:11px;cursor:pointer;font-family:inherit;">✅ 转职</button>';
                    } else {
                        html += '<span style="font-size:11px;color:#e74c3c;">缺 ' + check.missing.join('、') + '</span>';
                    }
                    html += '</div>';
                });
            });
            html += '</div>';
            document.getElementById('job-change-body').innerHTML = html;
            document.getElementById('job-change-modal').style.display = 'flex';
        }
        async function doJobChange(target, newJob) {
            if (typeof Mvu === 'undefined') return alert('MVU 框架未初始化');
            var mvuData = currentMvuData();
            var stat = mvuData.stat_data;
            var actor = allocActor(stat, target);
            if (!actor) return alert('未找到角色数据');
            var jobInfo = (actor.基础状态 && actor.基础状态.职业信息) || {};
            var mainJob = Object.keys(jobInfo)[0] || '';
            if (mainJob === newJob) return alert('已是该职业');
            var check = jobReqCheck(actor, newJob);
            if (!check.ok) return alert('属性不足，无法转职：缺 ' + check.missing.join('、'));
            var sp = JOB_GROWTH_SP[newJob] || 0;
            var msg;
            if (mainJob) {
                // 已有主职业：转职替换（保留等级，技能点按新职业成长，兼职保留）
                var oldLv = parseInt(jobInfo[mainJob].等级, 10) || 1;
                Object.keys(jobInfo).forEach(function (j) { if (j === newJob) delete jobInfo[j]; });
                delete jobInfo[mainJob];
                jobInfo[newJob] = { 等级: oldLv, 技能点: sp * oldLv, grantedLv: -1, grantedSp: -1 };
                msg = '✅ 已转职为「' + newJob + '」：等级保留 ' + oldLv + '，技能点按新职业成长重置为 ' + (sp * oldLv) + '，兼职已保留。';
            } else {
                // 无职业：直接新建职业（Lv.1）
                jobInfo[newJob] = { 等级: 1, 技能点: sp, grantedLv: -1, grantedSp: -1 };
                msg = '✅ 已为角色新建职业「' + newJob + '」（Lv.1，技能点 ' + sp + '）。';
            }
            var ok = await persistStatChange(mvuData);
            if (ok) {
                document.getElementById('job-change-modal').style.display = 'none';
                alert(msg);
            }
        }

                // 年龄成长曲线：1~18 岁累计 20 购点（>18 封顶 20，不再计算）
        // 三段：1-5岁 +0.75/岁、6-12岁 +1/岁、13-18岁 +10/6每岁
        function ageGrowthPoints(age) {
            var a = parseInt(age, 10) || 0;
            if (a >= 18) return 20;
            if (a > 12) return 10 + Math.round((a - 12) * 10 / 6);
            if (a > 5) return 3 + (a - 5);
            if (a > 1) return Math.round((a - 1) * 0.75);
            return 0;
        }
        // 年龄成长系统开关（首页创建器可关）：关闭后主动/被动都不再发放年龄成长点
        function ageGrowthEnabled() {
            try { return localStorage.getItem('isuria_age_growth') !== '0'; } catch (e) { return true; }
        }
        // 年龄成长补点：基础属性（扣种族加成）基线 48，1-18 岁累计 20 购点，不足则补到未分配点数
                // 计算年龄成长差额（主动/被动共用；skip=true 表示无年龄）
        // 只认 $flags.年龄成长 发放记录，不看总属性——升级所得属性点不干扰年龄成长
        // 年龄成长记录读/写：存酒馆 chat 变量（与 MVU schema 校验解耦，跨楼层 100% 持久，不因 AI 变量更新丢失）
        // 本聊天唯一键（per-chat 首次判定，避免 initvar 预置的 年龄成长:0 被误当作"已记录"）
        function ageChatKey() {
            var cid = 'default';
            try { if (typeof getCurrentChatId === 'function') cid = getCurrentChatId() || 'default'; } catch (e) {}
            return 'iz_age_init_' + cid;
        }
        function readAgeGrowthIssued() {
            // 优先 Mvu API（与 MVU 内存同步，不被下一楼变量重建覆盖回旧值）
            try {
                if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
                    var md = Mvu.getMvuData({ type: 'chat' });
                    return parseInt(_.get(md, 'stat_data.$flags.年龄成长', 0), 10) || 0;
                }
            } catch (e) {}
            try {
                var v = typeof getVariables === 'function' ? getVariables({ type: 'chat' }) : {};
                return parseInt(_.get(v, 'stat_data.$flags.年龄成长', 0), 10) || 0;
            } catch (e) { return 0; }
        }
        function writeAgeGrowthIssued(val) {
            try {
                try { localStorage.setItem(ageChatKey(), '1'); } catch (e) {}
                if (typeof Mvu !== 'undefined' && Mvu.getMvuData && Mvu.replaceMvuData) {
                    var md = Mvu.getMvuData({ type: 'chat' });
                    _.set(md, 'stat_data.$flags.年龄成长', val);
                    Mvu.replaceMvuData(md, { type: 'chat' });
                    return;
                }
                var v = typeof getVariables === 'function' ? getVariables({ type: 'chat' }) : {};
                _.set(v, 'stat_data.$flags.年龄成长', val);
                if (typeof replaceVariables === 'function') replaceVariables(v, { type: 'chat' });
            } catch (e) { console.warn('[年龄成长] 记录写入失败:', e); }
        }
        function hasAgeGrowthRecord() {
            // 首次判定（二重）：①本聊天已运行过（localStorage per-chat 标记）②MVU 记录 >0
            // initvar 预置的 年龄成长:0 不再被误判为"已记录"（此前导致开局即补满 20 点并每楼弹窗）
            try { if (localStorage.getItem(ageChatKey()) === '1') return true; } catch (e) {}
            try { if (readAgeGrowthIssued() > 0) return true; } catch (e) {}
            return false;
        }
        function calcAgeGrowth(stat, actor) {
            var age = parseInt(_.get(actor, '基础信息.年龄', 0), 10) || 0;
            if (age <= 0) return { age: age, expected: 0, issued: 0, missing: 0, skip: true };
            var issued = readAgeGrowthIssued();
            var expected = ageGrowthPoints(age);
            // 首次（从未发放过，新角色/新存档）：按当前年龄作为已应得基线，
            // 避免高龄开局/已满年龄被重复补点（如 30 岁开局不应再补 20 点）
            var firstTime = !hasAgeGrowthRecord();
            if (firstTime) issued = expected;
            return { age: age, expected: expected, issued: issued, missing: Math.max(0, expected - issued), skip: false, firstTime: firstTime };
        }
        // 主动（按钮）：弹提示
        async function applyAgeGrowth(target) {
            if (!ageGrowthEnabled()) return alert('年龄成长系统已关闭（请在首页创建器的"年龄成长系统"开关中开启）。');
            if (typeof Mvu === 'undefined') return alert('MVU 框架未初始化');
            var mvuData = currentMvuData();
            var stat = mvuData.stat_data;
            var actor = allocActor(stat, target);
            if (!actor) return alert('未找到角色数据');
            var r = calcAgeGrowth(stat, actor);
            if (r.skip) { alert('未读取到年龄（基础信息.年龄），请先设定年龄。'); return; }
            if (r.firstTime) {
                // 首次：按初始年龄记录已应得点数，不发多余点（高龄开局/已满年龄不再重复补）
                stat.$flags = stat.$flags || {};
                stat.$flags.年龄成长 = r.expected;
                writeAgeGrowthIssued(r.expected);
                await persistStatChange(mvuData);
                alert('开局年龄已含年龄成长：' + r.age + '岁应得 ' + r.expected + '/20 点（已按初始年龄记录，不重复发放；后续随年龄增长自动补齐）。');
                return;
            }
            if (r.missing > 0) {
                actor.基础属性.未分配点数 = (parseInt(_.get(actor, '基础属性.未分配点数', 0), 10) || 0) + r.missing;
                stat.$flags = stat.$flags || {};
                stat.$flags.年龄成长 = r.expected;
                writeAgeGrowthIssued(r.expected);
                await persistStatChange(mvuData);
                alert('🎂 年龄成长：' + r.age + '岁 应得 ' + r.expected + '/20 点，已补 ' + r.missing + ' 点到未分配属性点（累计发放 ' + r.expected + ' 点）。升级所得属性点不会干扰年龄成长。');
            } else {
                alert('年龄成长已到位：' + r.age + '岁，应得 ' + r.expected + '/20，已发放 ' + r.issued + ' 点，无需补点。');
            }
        }
        // 被动（每层静默）：只要年龄在成长区间且未发满，就自动补
        async function passiveAgeGrowthCheck() {
            if (typeof Mvu === 'undefined') return;
            if (!ageGrowthEnabled()) return; // 首页开关关闭 → 完全不发放
            try {
                var mvuData = currentMvuData();
                var stat = mvuData.stat_data;
                var actor = allocActor(stat, '主角');
                if (!actor) return;
                var age = parseInt(_.get(actor, '基础信息.年龄', 0), 10) || 0;
                // 已成年（>18岁）不再补发：18 岁那天领满 20，之后完全停止，避免成年后仍被补全
                if (age > 18) return;
                var r = calcAgeGrowth(stat, actor);
                if (r.skip) return;
                if (r.firstTime) {
                    // 首次：仅初始化发放记录，不发多余点
                    stat.$flags = stat.$flags || {};
                    stat.$flags.年龄成长 = r.expected;
                    writeAgeGrowthIssued(r.expected);
                    await persistStatChange(mvuData);
                    return;
                }
                if (r.missing <= 0) return;
                actor.基础属性.未分配点数 = (parseInt(_.get(actor, '基础属性.未分配点数', 0), 10) || 0) + r.missing;
                stat.$flags = stat.$flags || {};
                stat.$flags.年龄成长 = r.expected;
                writeAgeGrowthIssued(r.expected);
                await persistStatChange(mvuData);
                if (typeof toastr !== 'undefined' && toastr.info) toastr.info('🎂 年龄成长：' + r.age + '岁 自动获得 ' + r.missing + ' 点未分配属性点（累计发放 ' + r.expected + '/20）。');
            } catch (e) { console.warn('[年龄成长] 被动检测失败:', e); }
        }

        function allocStat() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            return all.stat_data || {};
        }
        function allocActor(stat, target) {
            if (!stat) return null;
            if (target === '主角') return stat.主角 || null;
            return _.get(stat, ['同伴', target], null);
        }
        // 技能写入槽位路径（相对 actor）：主角 → 资产与能力.{角色技能|魔法栏|神术栏}；同伴 → 技能
        function allocSlotPath(target, type) {
            if (target === '主角') return type === '魔法' ? '资产与能力.魔法栏' : (type === '神术' ? '资产与能力.神术栏' : '资产与能力.角色技能');
            return '技能';
        }
        // 已学技能集合
        function allocLearned(actor, target) {
            var map = {};
            if (!actor) return map;
            if (target === '主角') {
                ['角色技能', '魔法栏', '神术栏'].forEach(function(sk) {
                    Object.keys(_.get(actor, '资产与能力.' + sk, {})).forEach(function(k) { map[k] = true; });
                });
            } else {
                Object.keys(_.get(actor, '技能', {})).forEach(function(k) { map[k] = true; });
            }
            return map;
        }

        /* ===== 状态栏升级分配：有未分配属性/职业点时在对应行显示 +，点确认一次写回（复用 confirmAlloc） ===== */
        var QA_ATTRS = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
        function qaGetStat() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            return (all && all.stat_data) || {};
        }
        function qaGetPools() {
            var st = qaGetStat();
            var hero = st.主角 || {};
            var attr = hero.基础属性 || {};
            var bs = hero.基础状态 || {};
            return { unalloc: parseInt(attr.未分配点数, 10) || 0, attr: attr, pendJob: parseInt(bs.待分配职业等级, 10) || 0, jobInfo: bs.职业信息 || {} };
        }
        // 草稿已占用的未分配点数/待分配职业等级
        function qaGetUsed() {
            var used = { au: 0, ju: 0 };
            if (!allocDraft || !allocDraft['主角']) return used;
            var d = allocDraft['主角'];
            Object.keys(d.attr || {}).forEach(function(a) { var v = d.attr[a] || 0; if (v > 0) used.au += v; });
            Object.keys(d.jobs || {}).forEach(function(j) { used.ju += d.jobs[j] || 0; });
            return used;
        }
        function qaMount() {
            var $lr = $('#level-info-row');
            if (!$lr || !$lr.length) return;
            var $box = $lr.closest('.jrpg-box');
            if (!$box || !$box.length) return;
            // 确认条容器（常驻，populate 不会重建它）
            var $bar = $('#quick-add-bar');
            if (!$bar || !$bar.length) { $box.append('<div id="quick-add-bar"></div>'); $bar = $('#quick-add-bar'); }
            var p = qaGetPools();
            var used = qaGetUsed();
            var d = allocDraftFor('主角');
            var totalPend = used.au + used.ju;
            // （计数项外层虚线框保留；仅数字内框去掉，已由 CSS 处理）
            // 六维属性行：有额度显示 +；有待确认显示 +N 与 −
            $box.find('.jrpg-stat-item').each(function() {
                var $it = $(this);
                $it.find('.qa-plus, .qa-minus, .qa-pend').remove();
                var label = ($it.children('span').first().text() || '').replace(/^\s+|\s+$/g, '');
                var idx = QA_ATTRS.indexOf(label);
                if (idx < 0) return;
                var aname = QA_ATTRS[idx];
                var pend = d.attr[aname] || 0;
                var canAdd = (p.unalloc - used.au) > 0 && (parseInt(p.attr[aname], 10) || 10) < 30;
                if (canAdd || pend > 0) {
                    var $val = $it.children('span').eq(1);
                    if ($val && $val.length) {
                        if (pend > 0) $val.append('<span class="qa-pend">+' + pend + '</span>');
                        if (pend > 0) $val.append('<button type="button" class="qa-minus" data-qa-type="attr" data-qa-name="' + aname + '" title="减少 1 点「' + aname + '」的预分配">−</button>');
                        if (canAdd) $val.append('<button type="button" class="qa-plus' + (pend > 0 ? ' on' : '') + '" data-qa-type="attr" data-qa-name="' + aname + '" title="+' + (pend + 1) + ' 未分配属性点 → ' + aname + '">+</button>');
                    }
                }
            });
            // 职业信息行：有待分配职业等级（或已有待确认）才显示 + 与 −（加在职业名旁）
            var $jobs = $('#list-classes');
            if ($jobs && $jobs.length) {
                $jobs.find('.jrpg-list-item').each(function() {
                    var $li = $(this);
                    $li.find('.qa-plus, .qa-minus, .qa-pend').remove();
                    var $hd = $li.find('.jrpg-item-header').first();
                    if (!$hd || !$hd.length) return;
                    var $nm = $hd.children('span').first();
                    if (!$nm || !$nm.length) return;
                    var name = ($nm.text() || '').replace(/^⚔️\s*/, '').replace(/^\s+|\s+$/g, '');
                    if (!name) return;
                    var pend = d.jobs[name] || 0;
                    var canAdd = (p.pendJob - used.ju) > 0;
                    if (canAdd || pend > 0) {
                        if (pend > 0) $nm.append('<span class="qa-pend">+' + pend + '</span>');
                        if (pend > 0) $nm.append('<button type="button" class="qa-minus" data-qa-type="job" data-qa-name="' + escapeAttr(name) + '" title="减少 1 点「' + escapeAttr(name) + '」的预分配">−</button>');
                        if (canAdd) $nm.append('<button type="button" class="qa-plus' + (pend > 0 ? ' on' : '') + '" data-qa-type="job" data-qa-name="' + escapeAttr(name) + '" title="+' + (pend + 1) + ' 待分配职业等级 → ' + escapeAttr(name) + '">+</button>');
                    }
                });
            }
            // 操作条：仅在有待确认时出现（刷新 / 重置 / 确认分配）
            if (totalPend === 0) { $bar.html(''); return; }
            var h = '<button type="button" class="qa-btn-sm qa-refresh" title="重新读取当前未分配点数（保留已点待确认）">🔄 刷新</button>' +
                '<button type="button" class="qa-btn-sm qa-reset" title="清空本次已点的待确认分配">↺ 重置</button>' +
                '<button type="button" class="qa-confirm" title="把已点的属性点/职业等级一次性写入并扣除对应未分配点数">✅ 确认分配（' + totalPend + '）</button>';
            $bar.html(h);
