                        '请按「变量更新规则」的 JSONPatch 格式输出全部变量的更新（replace 六维与资源、insert 新技能、replace 技能点与职业等级等）；且本次 insert/replace 的新技能与升级后的既有技能，其「效果」词条必须电报式精简：每条≤20字，只写【效果+数值/骰子+范围/距离+持续/冷却】，禁止完整句式与形容词堆砌（风味叙述写在正文，不写入变量）。随后让这些更新生效。';
                }
                var sentMode = await emitAllocPrompt(msg);
                if (window.toastr) toastr.success(sentMode === 'inject' ? '🤖 AI 自动分配指令已注入上下文（下次生成生效）！' : '🤖 AI 自动分配指令已发送楼层！');
            } catch (e) {
