                renderTrackMoney();
            }
            function readTrackFullFlag() {
                try {
                    var mvuD = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    return !!(mvuD && mvuD.stat_data && mvuD.stat_data.$flags && mvuD.stat_data.$flags.追踪记录全量);
                } catch (e) { return false; }
            }
            function renderTrackMoney() {
                var box = document.getElementById('track-money'); if (!box) return;
                var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                var curMoney = mvuD && mvuD.stat_data && mvuD.stat_data.主角 && mvuD.stat_data.主角.资产与能力 ? mvuD.stat_data.主角.资产与能力.货币 : null;
                var lastMoney = lastTrackMoney();
                box.innerHTML = '<div style="font-size:12px;color:#4a3623;">stat_data.货币：<b>' + (curMoney === null ? '（未读取）' : formatCurrency(curMoney)) + '</b>　·　流水账最后余额：<b>' + (lastMoney === null ? '—' : formatCurrency(lastMoney)) + '</b></div>';
                box.innerHTML += '<div style="margin-top:6px;"><button id="btn-fix-money" class="jrpg-btn-sm" style="padding:3px 10px;font-size:11px;background:#27ae60;color:#fff;border:1px solid #27ae60;border-radius:4px;">🔧 一键修正货币为流水账余额</button><span style="font-size:11px;color:#7f8c8d;margin-left:6px;">若不一致，点击后把 stat_data.货币 写为流水账最后余额。</span></div>';
            }
            function lastTrackMoney() {
                var me = readTrack(), last = null;
                // 跳过经验获取条（与货币无关，余额恒 -1）与未知余额（-1），取最近一条有效货币余额
                me.forEach(function(e) { if (e.类型 !== '经验获取' && e.余额 !== undefined && e.余额 !== null && e.余额 >= 0) last = e.余额; });
                return last;
            }
            $('.jrpg-status-wrapper').on('click', '#btn-track-full', function() {
                try {
                    var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                    if (!mvuD || !mvuD.stat_data) return alert('MVU 未初始化');
                    mvuD.stat_data.$flags = mvuD.stat_data.$flags || {};
                    mvuD.stat_data.$flags.追踪记录全量 = !(mvuD.stat_data.$flags.追踪记录全量);
                    Promise.resolve(Mvu.replaceMvuData(mvuD, { type: 'message', message_id: 'latest' })).then(function() {
                        renderTrackTab();
                        toastr.success(mvuD.stat_data.$flags.追踪记录全量 ? '已切换：状态输出全量流水' : '已切换：状态输出近5条流水', '追踪记录');
                    });
                } catch (e) { toastr.error('切换失败：' + e.message); }
            });
            $('.jrpg-status-wrapper').on('click', '#btn-clear-track', function() {
                if (!confirm('确定清空所有追踪记录？此操作会清空 stat_data.世界.追踪记录 容器！')) return;
                try {
                    var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                    if (!mvuD || !mvuD.stat_data) return alert('MVU 未初始化');
                    if (!mvuD.stat_data.世界) return toastr.warning('世界容器不存在，无需清空');
                    mvuD.stat_data.世界.追踪记录 = {};
                    Promise.resolve(Mvu.replaceMvuData(mvuD, { type: 'message', message_id: 'latest' })).then(function() { renderTrackTab(); toastr.success('追踪记录已清空'); });
                } catch (e) { toastr.error('清空失败：' + e.message); }
            });
            $('.jrpg-status-wrapper').on('click', '#btn-fix-money', function() {
                try {
                    var target = lastTrackMoney(); if (target === null) return toastr.warning('流水账暂无余额记录，无法修正');
                    var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                    if (!mvuD || !mvuD.stat_data) return alert('MVU 未初始化');
                    mvuD.stat_data.主角 = mvuD.stat_data.主角 || {};
                    mvuD.stat_data.主角.资产与能力 = mvuD.stat_data.主角.资产与能力 || {};
                    mvuD.stat_data.主角.资产与能力.货币 = Math.max(0, target);
                    Promise.resolve(Mvu.replaceMvuData(mvuD, { type: 'message', message_id: 'latest' })).then(function() { toastr.success('货币已一键修正为 ' + Math.max(0, target)); renderTrackMoney(); });
                } catch (e) { toastr.error('修正失败：' + e.message); }
            });
            $('.jrpg-status-wrapper').on('click', '#btn-item-audit', function() {
                try {
                    var msg = '[系统·物品核对] 请核对你在近期叙事中涉及的所有物品售卖/删减/购买动作，与主角当前物品栏及各同伴物品栏逐条比对：若叙事中让角色获得或失去物品却未在对应物品栏体现，请立即在下一轮变量更新中修正；严禁把物品误写入主角或同伴之外的容器。';
                    if (typeof createChatMessages === 'function') createChatMessages([{ role: 'system', message: msg }]);
                    else if (typeof sendSystemMessage === 'function') sendSystemMessage('system', msg);
                    toastr.success('物品核对指令已发送');
                } catch (e) { toastr.error('发送失败：' + e.message); }
            });
            // 经验获取记录由经验确认弹窗回调 trackPush 写入（见 filterExperienceConfirmCommands）
            function trackPush(entry) {
                try {
                    var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                    if (!mvuD || !mvuD.stat_data) return;
                    mvuD.stat_data.世界 = mvuD.stat_data.世界 || {};
                    mvuD.stat_data.世界.追踪记录 = mvuD.stat_data.世界.追踪记录 || {};
                    var d = new Date();
                    var pad = function(n) { return (n < 10 ? '0' : '') + n; };
                    var key = '' + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + '-' + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds()) + '-' + Math.floor(Math.random() * 900 + 100);
                    if (mvuD.stat_data.世界.追踪记录[key]) { key = key + '-' + (Object.keys(mvuD.stat_data.世界.追踪记录).length + 1); }
                    mvuD.stat_data.世界.追踪记录[key] = {
                        时间: String(entry.时间 || (d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()))),
                        类型: String(entry.类型 || '其他'),
                        金额: parseInt(entry.金额, 10) || 0,
                        物品: String(entry.物品 || ''),
                        数量: parseInt(entry.数量, 10) || 0,
                        余额: (entry.余额 === undefined || entry.余额 === null || entry.余额 === '') ? -1 : (parseInt(entry.余额, 10) || 0),
                        说明: String(entry.说明 || '')
                    };
                    Mvu.replaceMvuData(mvuD, { type: 'message', message_id: 'latest' });
                } catch (e) {}
            }

            // ===== 👪 家族页签 + 🏪 产业页签：谱系展示/儿女培养计划 + 产业收益管理 =====
            // 数据源：stat_data.家族 = { 谱系说明, 成员: { 姓名: {称谓,世代,出生年月日,存亡,资质,魔力回路,等阶,基础属性,培养计划,培养记录,...} } }
            //         stat_data.产业 = { 产业名: { 类型,结算周期,每期收益,上次结算,状态,购入价,... } }
            // 培养计划/产业编辑由玩家在此直接写变量（message+chat 双写，仿 trtWriteTerritory）；
            // 周期成长与收益补算由「产业结算脚本」在 VARIABLE_UPDATE_ENDED 自动执行（本次只改显示与计划）。
            function famReadStatData() {
                try {
                    var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                    if (mvuD && _.isPlainObject(mvuD.stat_data) && Object.keys(mvuD.stat_data).length > 0) return mvuD.stat_data;
                } catch (e) {}
                var all = (typeof getAllVariables === 'function') ? getAllVariables() : {};
                return (_.isPlainObject(all) && _.isPlainObject(all.stat_data)) ? all.stat_data : {};
            }
            // 统一写入：基于最新楼层 stat_data 修改，回写 message(latest)+chat 两级（保证渲染与 AI 更新同源）
            async function famWriteStatData(mutate) {
                if (typeof Mvu === 'undefined') return;
                var mvuData = null;
                try { mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' }); } catch (e) { mvuData = null; }
                var hasStat = mvuData && _.isPlainObject(_.get(mvuData, 'stat_data')) && Object.keys(mvuData.stat_data).length > 0;
                if (!hasStat) {
                    var all = (typeof getAllVariables === 'function') ? getAllVariables() : {};
                    var base = _.isPlainObject(all) ? all : {};
                    mvuData = { initialized_lorebooks: _.get(mvuData, 'initialized_lorebooks', {}), stat_data: _.get(base, 'stat_data', {}) || {} };
                }
                if (!mvuData.stat_data) mvuData.stat_data = {};
                mutate(mvuData.stat_data);
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                try {
                    if (typeof updateVariablesWith === 'function') {
                        updateVariablesWith(function(variables) {
                            if (!variables || typeof variables !== 'object') variables = {};
                            variables.stat_data = mvuData.stat_data;
                            return variables;
                        }, { type: 'chat' });
                    }
                } catch (e) { console.warn('[家族产业] chat 级变量同步失败:', e); }
            }
            // '圣光历1497年3月' → 连续月索引；无法解析返回 null
            function famParseMonths(str) {
                var m = /圣光历\s*(\d+)\s*年(?:\s*(\d+)\s*月)?/.exec(String(str || ''));
                if (!m) return null;
                var y = parseInt(m[1], 10), mo = m[2] !== undefined ? parseInt(m[2], 10) : 1;
                if (!isFinite(y) || !isFinite(mo) || mo < 1 || mo > 12) return null;
                return y * 12 + (mo - 1);
            }
            function famMonthsToStr(idx) {
                return '圣光历' + Math.floor(idx / 12) + '年' + (idx % 12 + 1) + '月';
            }
            // 本月成长概率(%)（与产业结算脚本同式）：资质基础率×方向契合×年龄段×费用系数×0.25，clamp 5%~90%
            function famGrowthChance(m) {
                var plan = (m.培养计划 && typeof m.培养计划 === 'object') ? m.培养计划 : {};
                if (!plan.方向) return null;
                var aptMap = { '低劣': 30, '平庸': 45, '普通': 55, '优秀': 70, '卓越': 85, '天才': 100 };
                var apt = aptMap[_.get(m, '资质.等级', '平庸')] || 45;
                var f = 1;
                if (plan.方向 === '魔法') {
                    f *= (_.get(m, '魔力回路.品阶', '无回路') !== '无回路') ? 1.1 : 0.8;
                } else {
                    var pools = { '武技': '力量', '信仰': '感知', '学识': '智力', '商业': '魅力', '技艺': '敏捷', '综合': '力量' };
                    var mainAttr = pools[plan.方向];
                    if (mainAttr) {
                        var a = (m.基础属性 && typeof m.基础属性 === 'object') ? m.基础属性 : {};
                        if ((parseInt(a[mainAttr], 10) || 10) >= 13) f *= 1.1;
                    }
                }
                var age = calcActorAge(m);
                if (age !== null && age !== undefined) {
                    if (age < 3) f *= 0.4;
                    else if (age < 6) f *= 0.7;
                    else if (age >= 13 && age < 17) f *= 1.25;
                }
                if ((parseInt(plan.每期投入, 10) || 0) <= 0) f *= 0.8;   // 家中自行指点
                return Math.max(5, Math.min(90, Math.round(apt * f * 0.25)));
            }
            function famCurMonthIndex() {
                var all = (typeof getAllVariables === 'function') ? getAllVariables() : {};
                return famParseMonths(_.get(all, 'stat_data.世界.日期', ''));
            }
            var FAMILY_GROUPS = [
                { key: '祖辈', titles: ['祖父', '祖母', '外祖父', '外祖母'] },
                { key: '父母辈', titles: ['父亲', '母亲'] },
                { key: '同辈', titles: ['兄', '姐', '弟', '妹', '配偶'] },
                { key: '子辈', titles: ['儿子', '女儿'] },
                { key: '亲戚及其他', titles: ['亲戚', '其他'] }
            ];
            function famGroupOf(m) {
                var gen = String(m.世代 || '');
                for (var gi = 0; gi < FAMILY_GROUPS.length; gi++) { if (gen === FAMILY_GROUPS[gi].key) return FAMILY_GROUPS[gi].key; }
                var t = String(m.称谓 || '');
                for (var gj = 0; gj < FAMILY_GROUPS.length; gj++) { if (FAMILY_GROUPS[gj].titles.indexOf(t) !== -1) return FAMILY_GROUPS[gj].key; }
                return '亲戚及其他';
            }
            function famStatusBadge(alive) {
                if (alive === '已故') return '<span style="font-size:10px;color:#fff;background:#7f8c8d;border-radius:8px;padding:1px 6px;">已故</span>';
                if (alive === '失踪') return '<span style="font-size:10px;color:#fff;background:#e67e22;border-radius:8px;padding:1px 6px;">失踪</span>';
                if (alive === '已独立') return '<span style="font-size:10px;color:#fff;background:#2980b9;border-radius:8px;padding:1px 6px;">已独立</span>';
                return '<span style="font-size:10px;color:#fff;background:#27ae60;border-radius:8px;padding:1px 6px;">在世</span>';
            }
            function readFamilyData() {
                var f = famReadStatData().家族;
