        function showRelmapTip(node) {
            if (!node) return;
            var nm = $(node).data('npc');
            var all2 = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var npc = _.get(all2, ['stat_data', '主要NPC', nm], null);
            if (!npc) return;
            $('.jrpg-relmap-tip').html(relmapDetailHtml(nm, npc));
            var r = node.getBoundingClientRect();
            $('.jrpg-relmap-tip').css({ left: Math.min(window.innerWidth - 300, r.left + r.width / 2 - 130), top: 0 }).show();
            // 定位校正：先显示再按实际高度收拢，避免内容超出视口底部被截断
            var tipH = $('.jrpg-relmap-tip').outerHeight() || 0;
            var desired = r.top - 10;
            var maxTop = window.innerHeight - tipH - 8;
            var top = Math.min(desired, Math.max(8, maxTop));
            $('.jrpg-relmap-tip').css('top', top);
        }

        $(document).on('touchstart', '.jrpg-relmap-doc-item', function () {
            var self = this;
            relmapLongPress = setTimeout(function () { relmapPinned = 'lp'; showRelmapTip(self); }, 600);
        }).on('touchend touchmove touchcancel', '.jrpg-relmap-doc-item', function () {
            clearTimeout(relmapLongPress);
        });
        $(document).on('click', '.jrpg-relmap-doc-item', function () {
            var nm = $(this).data('npc');
            if (relmapPinned === nm) { relmapPinned = null; $('.jrpg-relmap-tip').hide(); return; }
            relmapPinned = nm;
            showRelmapTip(this);
        });
