            if (path.indexOf('自身状态') !== -1) {
                var desc = prompt('状态描述（如：每轮受1d4毒素伤害）：') || '';
                var type = prompt('状态类型（增益/减益/中性，默认中性）：') || '中性';
                if (['增益', '减益', '中性'].indexOf(type) === -1) type = '中性';
                newVal = { 描述: desc, 类型: type };
            }
            _.set(editorDataCopy, path + '.' + name.trim(), newVal);
            vtCommitWriteback();
        });
        // ★ 修改模式：条目垃圾桶删除（自动写回 + 热加载）
        $('.jrpg-status-wrapper').on('click', '.jrpg-del-tag', function (e) {
            e.stopPropagation();
            if (!editMode) return;
            var path = $(this).data('del-path');
            if (!path) return;
            if (!confirm('确定删除 [' + path + '] 吗？此操作立即写回，无法撤销！')) return;
            var pathArr = path.split('.');
            if (pathArr.length === 1) { delete editorDataCopy[path]; }
            else {
                var key = pathArr.pop();
                var parentPath = pathArr.join('.');
                var parentObj = _.get(editorDataCopy, parentPath);
                if (Array.isArray(parentObj)) parentObj.splice(parseInt(key), 1);
                else delete parentObj[key];
            }
            vtCommitWriteback();
        });

        // 同伴属性锁定/解锁按钮
        $('.jrpg-status-wrapper').on('click', '.jrpg-attr-lock-btn', function() {
            toggleCompAttrLock($(this).data('comp'));
        });

            // ===== 转职 & 年龄成长事件 =====
            $('.jrpg-status-wrapper').on('click', '.jrpg-change-job', function () { renderJobChangeModal($(this).data('target')); });
            $('.jrpg-status-wrapper').on('click', '.jrpg-do-jobchange', function () { doJobChange($(this).data('target'), $(this).data('job')); });
            $('.jrpg-status-wrapper').on('click', '.jrpg-age-grow', function () { applyAgeGrowth($(this).data('target')); });
            $('#btn-close-job-change, #btn-close-job-change-2').on('click', function () { $('#job-change-modal').css('display', 'none'); });
            // ===== 升级分配事件 =====
            $('.jrpg-status-wrapper').on('click', '.alloc-mode-btn', async function() {
                await setAllocInjectMode($(this).data('alloc-mode'));
                renderAllocCenter();
            });
            $('.jrpg-status-wrapper').on('click', '.alloc-target-btn', function() {
                allocTarget = $(this).data('alloc-target');
                renderAllocCenter();
            });
            $('.jrpg-status-wrapper').on('click', '.alloc-step-btn', function() {
                var $btn = $(this);
                var delta = parseInt($btn.data('delta'), 10) || 0;
                var draft = allocDraftFor(allocTarget);
                if ($btn.data('alloc-attr') !== undefined) {
                    var a = $btn.data('alloc-attr');
                    draft.attr[a] = (draft.attr[a] || 0) + delta;
                } else if ($btn.data('alloc-job') !== undefined) {
                    var j = $btn.data('alloc-job');
                    draft.jobs[j] = (draft.jobs[j] || 0) + delta;
                }
                renderAllocCenter();
            });
            $('.jrpg-status-wrapper').on('click', '.alloc-add-skill', function() {
                var $btn = $(this);
                var draft = allocDraftFor(allocTarget);
                var sk = {
                    job: $btn.data('alloc-skill-job'),
                    name: $btn.data('alloc-skill-name'),
                    type: $btn.data('alloc-skill-type'),
                    cost: parseInt($btn.data('alloc-skill-cost'), 10) || 1,
                    desc: $btn.data('alloc-skill-desc') || '',
                    mp: parseInt($btn.data('alloc-skill-mp'), 10) || 0
                };
                if (!draft.skills.some(function(s) { return s.name === sk.name && s.job === sk.job; })) {
                    draft.skills.push(sk);
                }
                renderAllocCenter();
            });
            $('.jrpg-status-wrapper').on('click', '.alloc-rm', function() {
                if (!allocDraft) return;
                var draft = allocDraft[allocTarget];
                if (!draft) return;
                var $btn = $(this);
                if ($btn.data('alloc-rm-attr') !== undefined) delete draft.attr[$btn.data('alloc-rm-attr')];
                else if ($btn.data('alloc-rm-job') !== undefined) delete draft.jobs[$btn.data('alloc-rm-job')];
                else if ($btn.data('alloc-rm-skill') !== undefined) draft.skills.splice(parseInt($btn.data('alloc-rm-skill'), 10), 1);
                renderAllocCenter();
            });
            $('.jrpg-status-wrapper').on('click', '#alloc-confirm-btn', confirmAlloc);
            $('.jrpg-status-wrapper').on('click', '#alloc-ai-btn', injectAiAlloc);
            $('.jrpg-status-wrapper').on('click', '#alloc-reset-btn', function() {
                if (allocDraft) delete allocDraft[allocTarget];
                renderAllocCenter();
            });
            // 状态栏升级分配行内 + 事件（复用主角 allocDraft + confirmAlloc）
            $('.jrpg-status-wrapper').on('click', '.qa-plus', function() {
                var $b = $(this);
                var type = $b.data('qa-type');
                var name = $b.data('qa-name');
                if (!type || !name) return;
                var p = qaGetPools();
                var used = qaGetUsed();
                var d = allocDraftFor('主角');
                if (type === 'attr') {
                    if ((p.unalloc - used.au) <= 0) return;
                    if ((parseInt(p.attr[name], 10) || 10) >= 30) return;
                    d.attr[name] = (d.attr[name] || 0) + 1;
                } else if (type === 'job') {
                    if ((p.pendJob - used.ju) <= 0) return;
                    d.jobs[name] = (d.jobs[name] || 0) + 1;
                }
                qaMount();
            });
            $('.jrpg-status-wrapper').on('click', '.qa-minus', function() {
                var $b = $(this);
                var type = $b.data('qa-type');
                var name = $b.data('qa-name');
                if (!type || !name) return;
                var d = allocDraftFor('主角');
                if (type === 'attr') { if ((d.attr[name] || 0) > 0) { d.attr[name] -= 1; if (!d.attr[name]) delete d.attr[name]; } }
                else if (type === 'job') { if ((d.jobs[name] || 0) > 0) { d.jobs[name] -= 1; if (!d.jobs[name]) delete d.jobs[name]; } }
                qaMount();
            });
            $('.jrpg-status-wrapper').on('click', '.qa-reset', function() {
                if (allocDraft) delete allocDraft['主角'];
                qaMount();
            });
            $('.jrpg-status-wrapper').on('click', '.qa-refresh', function() {
                if (typeof populateCharacterData === 'function') { try { populateCharacterData(); } catch (e) { console.error('刷新失败:', e); } }
            });
            $('.jrpg-status-wrapper').on('click', '.qa-confirm', function() {
                if (typeof confirmAlloc === 'function') { try { confirmAlloc(); } catch (e) { console.error('升级分配确认失败:', e); } }
            });
        }
        $(errorCatched(init));
    </script>
