        .content { position: relative; z-index: 2; line-height: 1.85; font-size: 0.95em; animation: scrollIn .65s ease-out; }
        @keyframes scrollIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

        /* ===== 卷轴本体：羊皮纸 + 暗角 + 横线 + 噪点 ===== */
        .scroll {
            padding: 40px 32px 46px;
