    <script>
        function parseSimpleYaml(text) {
            var lines = text.split('\n');
            var result = {};
            var currentSection = null;
            var currentSubSection = null;

            for (var i = 0; i < lines.length; i++) {
                var line = lines[i];
                if (line.trim() === '') continue;

                var indent = line.search(/\S/);
                var content = line.trim();

                if (indent === 0 && content.endsWith(':')) {
                    result._type = content.replace(':', '');
                    currentSection = null;
                    currentSubSection = null;
                    continue;
                }

                if (indent === 2 && content.indexOf(':') > 0) {
                    var parts = content.split(':');
                    var key = parts[0].trim();
                    var value = parts.slice(1).join(':').trim();

                    if (value === '' || value === '|') {
                        currentSection = key;
                        result[key] = {};
                        currentSubSection = null;
                    } else {
                        result[key] = value;
                        currentSection = null;
                        currentSubSection = null;
                    }
                    continue;
                }

                if (indent === 4 && currentSection) {
                    if (content.startsWith('- ')) {
                        var item = content.substring(2);
                        if (!Array.isArray(result[currentSection])) {
                            result[currentSection] = [];
                        }
                        result[currentSection].push(item);
                    } else if (content.indexOf(':') > 0) {
                        var parts2 = content.split(':');
                        var key2 = parts2[0].trim();
                        var value2 = parts2.slice(1).join(':').trim();
                        if (typeof result[currentSection] !== 'object' || Array.isArray(result[currentSection])) {
                            result[currentSection] = {};
                        }
                        if (value2 === '') {
                            currentSubSection = key2;
                            result[currentSection][key2] = [];
                        } else {
                            result[currentSection][key2] = value2;
                        }
                    }
                    continue;
                }

                if (indent === 6 && currentSection) {
                    if (content.startsWith('- ')) {
                        var item2 = content.substring(2);
                        if (currentSubSection && result[currentSection][currentSubSection]) {
                            result[currentSection][currentSubSection].push(item2);
                        } else if (Array.isArray(result[currentSection])) {
                            result[currentSection].push(item2);
                        }
                    } else if (content.indexOf(':') > 0) {
                        var parts3 = content.split(':');
                        var key3 = parts3[0].trim();
                        var value3 = parts3.slice(1).join(':').trim();
                        if (typeof result[currentSection] === 'object' && !Array.isArray(result[currentSection])) {
                            result[currentSection][key3] = value3;
                        }
                    }
                    continue;
                }

                if (indent >= 6 && content.startsWith('- ')) {
                    var deepItem = content.substring(2);
                    if (currentSection && Array.isArray(result[currentSection])) {
                        result[currentSection].push(deepItem);
                    } else if (currentSection && currentSubSection && result[currentSection] && Array.isArray(result[currentSection][currentSubSection])) {
                        result[currentSection][currentSubSection].push(deepItem);
                    }
                }
            }
            return result;
        }

        /* 处理品阶映射，增加加护和权能的专属品阶 */
        function getRarityBase(rarity) {
            if (!rarity) return '普通';

            // 命格 / 神话
            if (rarity.indexOf('命格') >= 0 || rarity.indexOf('神话') >= 0) return '神话';
            // 神授 / 传说
            if (rarity.indexOf('神授') >= 0 || rarity.indexOf('传说') >= 0) return '传说';
            // 恩赐 / 史诗 / 稀有 (恩赐按设定算较高，这里映射为稀有或史诗，用稀有色较贴合蓝光)
            if (rarity.indexOf('史诗') >= 0) return '史诗';
            if (rarity.indexOf('恩赐') >= 0 || rarity.indexOf('稀有') >= 0) return '稀有';
            // 回响 / 精良
            if (rarity.indexOf('回响') >= 0 || rarity.indexOf('精良') >= 0) return '精良';
            // 权能 / 唯一
            if (rarity.indexOf('权能') >= 0 || rarity.indexOf('唯一') >= 0) return '唯一';

            return '普通';
        }

        function getTypeIcon(type) {
            var icons = {
                '技能': '✦',
                '武器': '⚔',
                '防具': '🛡',
                '饰品': '◈',
                '消耗品': '⬡',
                '材料': '◇',
                '任务': '📜',
                '加护与权能': '❂',
                '物品': '🔮'
            };
            return icons[type] || '◆';
        }

        function renderField(key, value) {
            if (!value || value === '无' || value === '') return '';
            return '<div class="field-row"><span class="field-key">' + key + '</span><span class="field-value">' + value + '</span></div>';
        }

        function renderEffects(items, cls) {
            if (!items) return '';
            var html = '';
            var className = cls || '';
            if (Array.isArray(items)) {
                items.forEach(function(item) {
                    if (item && item !== '无') {
                        html += '<div class="effect-item ' + className + '">' + item + '</div>';
                    }
                });
            } else if (typeof items === 'string' && items !== '无') {
                html += '<div class="effect-item ' + className + '">' + items + '</div>';
            }
            return html;
        }

        function renderDivider() {
            return '<div class="divider"><div class="divider-line"></div><div class="divider-gem"></div><div class="divider-line"></div></div>';
        }

        /* ========== 渲染加护/权能 ========== */
        function renderBlessing(data) {
            var rarity = getRarityBase(data['品阶'] || '回响');
            var name = data['名称'] || '未知烙印';
            var html = '';

            html += '<div class="card-crown"></div>';

            html += '<div class="card-header">';
            html += '<div class="header-icon">❂</div>';
            html += '<div class="header-info">';
            html += '<div class="item-name">' + name + '</div>';
            html += '<div class="item-sub">' + (data['类型'] || '加护') + ' · ' + (data['来源'] || '本源意志') + '</div>';
            html += '</div>';
            html += '<div class="rarity-badge">' + (data['品阶'] || '回响') + '</div>';
            html += '</div>';

            html += renderDivider();

            html += '<div class="card-body">';

            /* 效果 */
            var effects = data['效果'];
            if (effects && effects.length > 0) {
                html += '<div class="section">';
                html += '<div class="section-title">✦ 法则干涉 ✦</div>';
                html += renderEffects(effects);
                html += '</div>';
            }

            /* 代价 */
            var penalties = data['代价'];
            if (penalties && penalties.length > 0 && penalties !== '无') {
                html += '<div class="section">';
                html += '<div class="section-title">✦ 承载代价 ✦</div>';
                html += renderEffects(penalties, 'penalty');
                html += '</div>';
            }

            html += '</div>';

            html += '<div class="card-footer">';
            html += '<span class="footer-weight">状态: 已刻入灵魂</span>';
            html += '</div>';

            if (data['描述'] && data['描述'] !== '无') {
                html += '<div class="card-lore">' + data['描述'] + '</div>';
            }

            return html;
        }

        /* ========== 渲染物品 ========== */
        function renderItem(data) {
            var type = '物品';
            var rarity = getRarityBase(data['品阶'] || '普通');
            var name = data['名称'] || '未知物品';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">' + getTypeIcon(type) + '</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || type) + ' · ' + (data['来源'] || '未知') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通') + '</div></div>' + renderDivider() + '<div class="card-body">';

            if (data['效果']) {
                html += '<div class="section"><div class="section-title">✦ 物品特性 ✦</div>' + renderEffects(data['效果']) + '</div>';
            }

            html += '</div><div class="card-footer"><span class="footer-price">◈ ' + (data['价格'] || '—') + '</span>';
            if (data['重量']) html += '<span class="footer-weight">⚖ ' + data['重量'] + '</span>';
            if (data['堆叠']) html += '<span class="footer-weight">堆叠: ' + data['堆叠'] + '</span>';
            html += '</div>';

            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderEquipment(data, type) {
            var rarity = getRarityBase(data['品阶'] || '普通');
            var name = data['名称'] || '未知物品';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">' + getTypeIcon(type) + '</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || type) + ' · ' + (data['来源'] || '未知') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通') + '</div></div>' + renderDivider() + '<div class="card-body">';
            if (data['基础属性']) { html += '<div class="section"><div class="section-title">✦ 基础属性 ✦</div>'; Object.keys(data['基础属性']).forEach(function(k) { html += renderField(k, data['基础属性'][k]); }); html += '</div>'; }
            if (data['装备位']) { html += '<div class="section">' + renderField('装备位', data['装备位']) + '</div>'; }
            if (data['词条']) { html += '<div class="section"><div class="section-title">✦ 附魔铭文 ✦</div>' + renderEffects(data['词条']) + '</div>'; }
            if (data['特殊机制']) { html += '<div class="section"><div class="section-title">✦ 特殊机制 ✦</div>' + renderEffects(data['特殊机制'], 'mechanic') + '</div>'; }
            if (data['情境效果']) { html += '<div class="section"><div class="section-title">✦ 情境共鸣 ✦</div>' + renderEffects(data['情境效果'], 'context') + '</div>'; }
            html += '</div><div class="card-footer"><span class="footer-price">◈ ' + (data['价格'] || '—') + '</span>';
            if (data['重量']) html += '<span class="footer-weight">⚖ ' + data['重量'] + '</span>';
            if (data['堆叠']) html += '<span class="footer-weight">堆叠: ' + data['堆叠'] + '</span>';
            html += '</div>';
            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderSkill(data) {
            var name = data['名称'] || '未知技能';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">✦</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['所属职业'] || '通用') + ' · ' + (data['类型'] || '被动') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通级') + '</div></div>' + renderDivider() + '<div class="card-body">';
            if (data['消耗']) { html += '<div class="section">'; Object.keys(data['消耗']).forEach(function(k) { if(data['消耗'][k] && data['消耗'][k]!=='无') html += '<span class="cost-tag">' + k + ': ' + data['消耗'][k] + '</span>'; }); if (data['持续']) html += '<span class="cost-tag">持续: ' + data['持续'] + '</span>'; html += '</div>'; }
            if (data['解锁条件']) { html += '<div class="section"><div class="section-title">✦ 研习条件 ✦</div>'; Object.keys(data['解锁条件']).forEach(function(k) { html += renderField(k, Array.isArray(data['解锁条件'][k]) ? data['解锁条件'][k].join('、') : data['解锁条件'][k]); }); html += '</div>'; }
            if (data['效果']) { html += '<div class="section"><div class="section-title">✦ 术式效果 ✦</div>' + renderEffects(data['效果']) + '</div>'; }
            html += '</div>';
            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderConsumable(data) {
            var name = data['名称'] || '未知物品';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">⬡</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || '消耗品') + ' · ' + (data['来源'] || '未知') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通') + '</div></div>' + renderDivider() + '<div class="card-body">';
            if (data['使用条件']) html += '<div class="section"><span class="cost-tag">' + data['使用条件'] + '</span></div>';
            if (data['效果']) html += '<div class="section"><div class="section-title">✦ 药理效果 ✦</div>' + renderEffects(data['效果']) + '</div>';
            html += '</div><div class="card-footer"><span class="footer-price">◈ ' + (data['价格'] || '—') + '</span><span class="footer-weight">堆叠: ' + (data['堆叠'] || '否') + '</span></div>';
            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderMaterial(data) {
            var name = data['名称'] || '未知材料';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="header-icon">◇</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || '材料') + ' · ' + (data['来源'] || '未知') + '</div></div><div class="rarity-badge">' + (data['品阶'] || '普通') + '</div></div>' + renderDivider() + '<div class="card-body"><div class="section">' + renderField('用途', data['用途']) + renderField('DC修正', data['DC修正']) + '</div></div><div class="card-footer"><span class="footer-price">◈ ' + (data['价格'] || '—') + '</span><span class="footer-weight">堆叠: ' + (data['堆叠'] || '是') + '</span></div>';
            if (data['描述']) html += '<div class="card-lore">' + data['描述'] + '</div>';
            return html;
        }

        function renderQuest(data) {
            var rank = data['等级'] || 'D';
            var name = data['名称'] || '未知任务';
            var html = '<div class="card-crown"></div><div class="card-header"><div class="quest-rank rank-' + rank + '">' + rank + '</div><div class="header-info"><div class="item-name">' + name + '</div><div class="item-sub">' + (data['类别'] || '任务') + ' · ' + (data['发布方'] || '未知') + '</div></div><div class="rarity-badge" style="border-color:#a39c91;color:#6b6357;">' + (data['当前状态'] || '进行中') + '</div></div>' + renderDivider() + '<div class="card-body">';
            if (data['报酬']) { html += '<div class="section"><div class="section-title">✦ 悬赏报酬 ✦</div>'; Object.keys(data['报酬']).forEach(function(k) { if(data['报酬'][k] && data['报酬'][k]!=='无') html += renderField(k, data['报酬'][k]); }); html += '</div>'; }
            if (data['目标']) { html += '<div class="section"><div class="section-title">✦ 委托目标 ✦</div>'; data['目标'].forEach(function(obj) { if(typeof obj === 'string') { var statusCls = 'obj-active'; var textCls = ''; if(obj.indexOf('完成')>=0) { statusCls = 'obj-done'; textCls = 'done'; } else if(obj.indexOf('未解锁')>=0) { statusCls = 'obj-locked'; textCls = 'locked'; } html += '<div class="quest-obj"><div class="obj-dot ' + statusCls + '"></div><span class="obj-text ' + textCls + '">' + obj + '</span></div>'; } }); html += '</div>'; }
            if (data['备注']) html += '<div class="section"><div class="section-title">✦ 委托备注 ✦</div><div class="field-row"><span class="field-value" style="color:#7a6a50;font-size:12.5px;">' + data['备注'] + '</span></div></div>';
            html += '</div><div class="card-footer"><span class="footer-weight">编号: ' + (data['编号'] || '—') + '</span><span class="footer-weight">期限: ' + (data['期限'] || '无期限') + '</span></div>';
            return html;
        }

        function renderCard(data) {
            var type = data._type || '';
            var rarity = getRarityBase(data['品阶'] || '普通');
            var html = '';

            switch(type) {
                case '技能': html = renderSkill(data); break;
                case '武器': html = renderEquipment(data, '武器'); break;
                case '防具': html = renderEquipment(data, '防具'); break;
                case '饰品': html = renderEquipment(data, '饰品'); break;
                case '消耗品': html = renderConsumable(data); break;
                case '材料': html = renderMaterial(data); break;
                case '任务': html = renderQuest(data); rarity = '稀有'; break;
                case '加护与权能': html = renderBlessing(data); break;
                case '物品': html = renderItem(data); break;
                default: return '<div class="error">❌ 未识别的古卷: ' + type + '</div>';
            }

            return '<div class="game-card rarity-' + rarity + '">' + html + '</div>';
        }

        function init() {
            try {
                var rawEl = document.getElementById('raw-data');
                if (!rawEl) { document.getElementById('game-panel').innerHTML = '<div class="error">❌ 契约文书未找到</div>'; return; }
                var rawText = rawEl.textContent || rawEl.innerText || '';
                if (!rawText.trim()) { document.getElementById('game-panel').innerHTML = '<div class="error">❌ 契约文书空白</div>'; return; }
                var data = parseSimpleYaml(rawText);
                if (!data || !data._type) { document.getElementById('game-panel').innerHTML = '<div class="error">❌ 无法解译古卷文字</div>'; return; }
                document.getElementById('game-panel').innerHTML = renderCard(data);
            } catch(error) {
                document.getElementById('game-panel').innerHTML = '<div class="error">❌ ' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
