            var at=t.match(/\[属性\|力量([^\|]+)\|敏捷([^\|]+)\|体质([^\|]+)\|智力([^\|]+)\|感知([^\|]+)\|魅力([^\]]+)\]/);
            if(at){r.attr={str:parseInt(at[1])||0,dex:parseInt(at[2])||0,con:parseInt(at[3])||0,int:parseInt(at[4])||0,wis:parseInt(at[5])||0,cha:parseInt(at[6])||0};}
            var ax=/\[攻击\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/g,am;
            while((am=ax.exec(t))!==null){r.attacks.push({name:am[1],type:am[2],hit:am[3],dmg:am[4],eff:am[5]});}
            var bx=/\[能力\|([^\|]+)\|([^\]]+)\]/g,bm;
            while((bm=bx.exec(t))!==null){r.abilities.push({name:bm[1],desc:bm[2]});}
            var ox=/\[奥义\|([^\]]+)\]/g,om;
            while((om=ox.exec(t))!==null){r.ougis.push(om[1]);}
            var px=/\[权能\|([^\]]+)\]/g,pm;
            while((pm=px.exec(t))!==null){r.powers.push(pm[1]);}
            var mx=/\[机制\|([^\]]+)\]/g,mm;
            while((mm=mx.exec(t))!==null){r.mechanics.push(mm[1]);}
            r.appear=g(/\[外貌\|([^\]]+)\]/);
            r.personality=g(/\[性格\|([^\]]+)\]/);
            r.bgStory=g(/\[背景故事\|([^\]]+)\]/);
            r.blessing=g(/\[加护\|([^\]]*)\]/);
            r.attitude=g(/\[态度\|([^\]]+)\]/);
            r.affinity=parseInt(g(/\[好感度\|([^\]]+)\]/))||50;
            var fx=/\[功能\|([^\]]+)\]/g,fm;
            while((fm=fx.exec(t))!==null){r.functions.push(fm[1]);}
            r.status=g(/\[状态\|([^\]]*)\]/);
            r.loadVar=g(/\[载入变量\|([^\]]*)\]/);
            var eqx = /\[装备\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/g, eqm;
            while ((eqm = eqx.exec(t)) !== null) { r.equips.push({slot: eqm[1], name: eqm[2], desc: eqm[3]}); }
            var itx = /\[随身物品\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/g, itm;
            while ((itm = itx.exec(t)) !== null) { r.items.push({name: itm[1], qty: parseInt(itm[2]) || 1, desc: itm[3]}); }
            return r;
        }

        /* ========== 解析召唤物 ========== */
