            r.spd=parseInt(g(/\[移动速度\|([^\]]+)\]/))||0;
            r.init=parseInt(g(/\[先攻修正\|([^\]]+)\]/))||0;
            var at=t.match(/\[属性\|力量([^\|]+)\|敏捷([^\|]+)\|体质([^\|]+)\|智力([^\|]+)\|感知([^\|]+)\|魅力([^\]]+)\]/);
            if(at){r.attr={str:parseInt(at[1])||0,dex:parseInt(at[2])||0,con:parseInt(at[3])||0,int:parseInt(at[4])||0,wis:parseInt(at[5])||0,cha:parseInt(at[6])||0};}
            var ax=/\[攻击\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/g,am;
            while((am=ax.exec(t))!==null){r.attacks.push({name:am[1],type:am[2],hit:am[3],dmg:am[4],eff:am[5]});}
            var bx=/\[能力\|([^\|]+)\|([^\]]+)\]/g,bm;
            while((bm=bx.exec(t))!==null){r.abilities.push({name:bm[1],desc:bm[2]});}
            var ox=/\[奥义\|([^\]]+)\]/g,om;
            while((om=ox.exec(t))!==null){r.ougis.push(om[1]);}
            var px=/\[权能\|([^\]]+)\]/g,pm;
            while((pm=px.exec(t))!==null){r.powers.push(pm[1]);}
            var mx=/\[机制\|([^\]]+)\]/g,mm;
            while((mm=mx.exec(t))!==null){r.mechanics.push(mm[1]);}
            var br=t.match(/\[吐息\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/);
            if(br){r.breath={name:br[1],element:br[2],dmg:br[3],range:br[4],cd:br[5]};}
            r.weak=g(/\[弱点\|([^\]]*)\]/);
            r.resist=g(/\[抗性\|([^\]]*)\]/);
            r.immune=g(/\[免疫\|([^\]]*)\]/);
            r.appear=g(/\[外貌\|([^\]]+)\]/);
            r.personality=g(/\[性格\|([^\]]+)\]/);
            r.faction=g(/\[所属势力\|([^\]]+)\]/);
            r.bgStory=g(/\[背景故事\|([^\]]+)\]/);
            r.status=g(/\[状态\|([^\]]*)\]/);
            return r;
        }

        /* ========== 解析集群 ========== */
        function parseCluster(raw) {
            var r = {name:'',type:'',race:'',count:0,remain:0,itier:'',ilevel:0,avgHp:0,hpCur:0,hpMax:0,def:0,spd:0,init:0,smart:'',
                     attr:{str:0,dex:0,con:0,int:0,wis:0,cha:0},attacks:[],tactics:[],abilities:[],
                     ougis:[],powers:[],mechanics:[],
                     weak:'',resist:'',immune:'',loot:[],exp:0,appear:'',status:''};
            var m = raw.match(/<cluster_data>([\s\S]*?)<\/cluster_data>/);
            if(!m) return r;
            var t = m[1];
            var g = function(re){var x=t.match(re);return x?x[1]:'';};
            r.name=g(/\[名称\|([^\]]+)\]/);
            r.type=g(/\[种类\|([^\]]+)\]/);
            r.race=g(/\[种族\|([^\]]+)\]/);
            r.count=parseInt(g(/\[数量\|([^\]]+)\]/))||0;
            r.remain=parseInt(g(/\[剩余数量\|([^\]]+)\]/))||0;
            r.itier=g(/\[个体等阶\|([^\]]+)\]/);
            r.ilevel=parseInt(g(/\[个体等级\|([^\]]+)\]/))||0;
            r.avgHp=parseInt(g(/\[平均生命值\|([^\]]+)\]/))||0;
            var hp=t.match(/\[HP\|([^\|]+)\|([^\]]+)\]/);
            if(hp){r.hpCur=parseInt(hp[1])||0;r.hpMax=parseInt(hp[2])||0;}
            r.def=parseInt(g(/\[防御值\|([^\]]+)\]/))||0;
            r.spd=parseInt(g(/\[移动速度\|([^\]]+)\]/))||0;
            r.init=parseInt(g(/\[先攻修正\|([^\]]+)\]/))||0;
            r.smart=g(/\[智慧\|([^\]]+)\]/);
            var at=t.match(/\[属性\|力量([^\|]+)\|敏捷([^\|]+)\|体质([^\|]+)\|智力([^\|]+)\|感知([^\|]+)\|魅力([^\]]+)\]/);
            if(at){r.attr={str:parseInt(at[1])||0,dex:parseInt(at[2])||0,con:parseInt(at[3])||0,int:parseInt(at[4])||0,wis:parseInt(at[5])||0,cha:parseInt(at[6])||0};}
            var ax=/\[集群攻击\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/g,am;
            while((am=ax.exec(t))!==null){r.attacks.push({name:am[1],type:am[2],hit:am[3],dmg:am[4],eff:am[5]});}
            var tx=/\[战术\|([^\|]+)\|([^\]]+)\]/g,tm;
            while((tm=tx.exec(t))!==null){r.tactics.push({name:tm[1],desc:tm[2]});}
            var bx=/\[能力\|([^\|]+)\|([^\]]+)\]/g,bm;
            while((bm=bx.exec(t))!==null){r.abilities.push({name:bm[1],desc:bm[2]});}
            var ox=/\[奥义\|([^\]]+)\]/g,om;
            while((om=ox.exec(t))!==null){r.ougis.push(om[1]);}
            var px=/\[权能\|([^\]]+)\]/g,pm;
            while((pm=px.exec(t))!==null){r.powers.push(pm[1]);}
            var mx=/\[机制\|([^\]]+)\]/g,mm;
            while((mm=mx.exec(t))!==null){r.mechanics.push(mm[1]);}
            r.weak=g(/\[弱点\|([^\]]*)\]/);
            r.resist=g(/\[抗性\|([^\]]*)\]/);
            r.immune=g(/\[免疫\|([^\]]*)\]/);
            var lx=/\[战利品\|([^\|]+)\|([^\]]+)\]/g,lm;
            while((lm=lx.exec(t))!==null){r.loot.push({item:lm[1],rate:lm[2]});}
            r.exp=parseInt(g(/\[经验值\|([^\]]+)\]/))||0;
            r.appear=g(/\[外貌\|([^\]]+)\]/);
            r.status=g(/\[状态\|([^\]]*)\]/);
            return r;
        }

        function fmod(v){return v>0?'+'+v:v.toString();}
        function vc(v){return v>0?'v-pos':v<0?'v-neg':'v-zero';}
        function affc(v){return v>=70?'aff-hi':v>=40?'aff-md':'aff-lo';}

        /* ===== 奥义 / 权能 渲染块（史诗级大招 / 传说级法则之力） ===== */
        // ougis: 单行字符串数组，形如 "奥义名: 效果" 或 "奥义名（限定）: 效果"
        function ougiBlockList(list, secCls, secLabel, nameCls, descCls) {
            var h = '';
            if (!list || !list.length) return h;
            h += '<div class="' + secCls + '">' + secLabel + '</div>';
            for (var i = 0; i < list.length; i++) {
                var raw = String(list[i] || '').trim();
                if (!raw) continue;
                var idx = raw.indexOf(':');
                var nm = (idx > -1 ? raw.slice(0, idx) : raw).trim();
                var ds = (idx > -1 ? raw.slice(idx + 1) : '').trim();
                h += '<div class="' + (secCls === 'power-sec' ? 'power-block' : 'ougi-block') + '">';
                h += '<div class="' + nameCls + '">' + nm + '</div>';
                if (ds) h += '<div class="' + descCls + '">' + ds + '</div>';
                h += '</div>';
            }
            return h;
        }

        function mechBlockList(list, secCls, secLabel, nameCls, descCls) {
            var h = '';
            if (!list || !list.length) return h;
            h += '<div class="' + secCls + '">' + secLabel + '</div>';
            for (var i = 0; i < list.length; i++) {
                var raw = String(list[i] || '').trim();
                if (!raw) continue;
                var idx = raw.indexOf('：');
                var nm = (idx > -1 ? raw.slice(0, idx) : raw).trim();
                var ds = (idx > -1 ? raw.slice(idx + 1) : '').trim();
                h += '<div class="mech-block">';
                h += '<div class="' + nameCls + '">' + nm + '</div>';
                if (ds) h += '<div class="' + descCls + '">' + ds + '</div>';
                h += '</div>';
            }
            return h;
        }

        function typeIco(t){
            var m={'魔兽':'🐺','人类':'⚔','亚人':'👹','构装体':'⚙','不死生物':'💀','魔族':'👿'};
            return m[t]||'❓';
        }
        function raceIco(r){
            var m={'人类':'👤','精灵':'🧝','矮人':'⛏','兽人':'🐺','翼民':'🪶','海妖':'🧜','龙裔':'🐲','半身人':'🍀','地精':'👺','血族':'🧛','混血':'✨'};
