            html += '</div>';

            if (data.result) {
                var evalColor = isSuccess ? '#2f8f45' : '#c0392b';
                var evalText = isSuccess ? '时光让步，亡者重临。' : '时光之锚颤动，回溯受限。';
                html += '<div class="pA-eval" style="border-left-color:' + evalColor + ';">' + evalText + '</div>';
            }

            html += '<div class="pA-roll">—— 本源回廊 · 追索 ——</div>';
            html += '</div>';
            return html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML = '<div class="loading">\u2014 \u65E0\u6CD5\u83B7\u53D6\u6D88\u606F \u2014</div>';
                    return;
                }

                var type = detectType(messageText);

                if (type === 'death') {
                    var deathData = parseDeathReport(messageText);
                    document.getElementById('content').innerHTML = renderDeath(deathData);
                } else if (type === 'rewind') {
                    var rewindData = parseRewindData(messageText);
                    document.getElementById('content').innerHTML = renderRewind(rewindData);
                } else {
                    document.getElementById('content').innerHTML = '<div class="loading">\u2014 \u672A\u68C0\u6D4B\u5230\u7ED3\u7B97\u6570\u636E \u2014</div>';
                }
            } catch (error) {
                document.getElementById('content').innerHTML = '<div class="loading">\u2014 \u52A0\u8F7D\u5931\u8D25 \u2014</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
