        .aura { position: relative; padding: 20px 16px 24px; border-radius: 6px; background: radial-gradient(circle at 18% 8%, #f8f1e0 0%, #eee1c2 55%, #ddcba4 100%); border: 1px solid #9a7f4e; box-shadow: 0 12px 30px rgba(58,44,26,.28), inset 0 0 0 1px rgba(247,240,222,.55), inset 0 0 46px rgba(107,86,56,.10); animation: auraIn .6s ease-out; overflow: hidden; }
