        .ult-card { position: relative; margin: 12px 0 18px; padding: 14px 16px 16px; background: linear-gradient(180deg, #faf4e4, #f2e7cc); border: 1px solid #b09a6a; border-left: 4px solid #a03028; border-radius: 4px; box-shadow: 0 2px 10px rgba(107,86,56,.22), inset 0 0 26px rgba(107,86,56,.05); overflow: hidden; opacity: 0; }
