        .cost-chip.mp { color: #37456b; background: linear-gradient(180deg, rgba(74,90,138,.12), rgba(74,90,138,.04)); border-color: rgba(74,90,138,.45); }

        .card-head { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 12px; margin-bottom: 10px; position: relative; z-index: 1; }
        .card-title { font-size: 1.22em; font-weight: 800; letter-spacing: 2px; color: #4a3418; }
        .holder-tag { display: inline-block; padding: 2px 10px; border-radius: 2px; font-size: .76em; color: #5a4a2e; background: rgba(138,111,69,.10); border: 1px solid rgba(138,111,69,.40); }
        .job-tag { display: inline-block; padding: 2px 10px; border-radius: 2px; font-size: .76em; color: #4a5a3a; background: rgba(90,110,70,.10); border: 1px solid rgba(90,110,70,.40); }

