        .sys-tag.sys-unknown { color: #4a4234; background: rgba(107,86,56,.10); border-color: rgba(107,86,56,.45); }
        .sys-tag { display: inline-block; padding: 2px 10px; border-radius: 2px; font-size: .74em; letter-spacing: 1px; border: 1px solid; }

        /* ===== 内容层级（盖过装饰层）===== */
        .ult-card > .card-head, .ult-card > .tsplit, .ult-card > .p-row, .ult-card > .cost-row, .ult-card > .sec-title, .ult-card > .p-val { position: relative; z-index: 1; }

        /* ===== 底部 ===== */
        .foot { display: flex; align-items: center; justify-content: center; gap: 10px; margin-top: 14px; font-size: .8em; color: #6b5638; letter-spacing: 1px; }
