        /* ===== 主题切换 ===== */
        .theme-bar { position: absolute; top: 8px; right: 12px; z-index: 9; display: flex; gap: 4px; }
        .theme-btn { padding: 2px 9px; font-size: .72em; font-weight: 700; letter-spacing: 1px; border: 1px solid rgba(138,111,69,.55); border-radius: 999px; cursor: pointer; background: rgba(247,240,222,.9); color: #5a4a2e; transition: all .2s; }
        .theme-btn.active { background: linear-gradient(180deg, #a03028, #6b2012); color: #f5ead6; border-color: #6b2012; box-shadow: 0 1px 4px rgba(107,86,56,.35); }
        /* ===== 主题·皇权典金 ===== */
        body.theme-royal .aura { background: radial-gradient(circle at 18% 8%, #f6e9c6 0%, #ead5a4 55%, #d2ba84 100%); border-color: #9a7f4e; box-shadow: 0 12px 30px rgba(58,44,26,.28), inset 0 0 0 1px rgba(255,250,235,.5), inset 0 0 46px rgba(166,124,26,.12); }
        body.theme-royal .head-title { color: #4a3410; text-shadow: 0 1px 0 rgba(255,255,255,.5); }
