        body.theme-royal .p-val { color: #4a3a1a; }
        body.theme-royal .p-val.desc { background: linear-gradient(180deg, rgba(166,124,26,.10), rgba(166,124,26,.04)); border-color: rgba(166,124,26,.30); }
        body.theme-royal .sec-title { color: #7a5a10; }
