        body.theme-royal .sec-title::after { background: linear-gradient(90deg, rgba(166,124,26,.4), transparent); }
        body.theme-royal .uc-rim { background: linear-gradient(135deg, transparent 30%, rgba(166,124,26,.4) 50%, transparent 70%); }
        body.theme-royal .uc-glow { background: radial-gradient(circle, rgba(166,124,26,.15), transparent 66%); }
