        body.theme-royal .theme-btn { background: rgba(246,233,198,.9); color: #6b4e1e; border-color: rgba(166,124,26,.5); }
        body.theme-royal .theme-btn.active { background: linear-gradient(180deg, #b8902a, #8a6414); }

        /* ===== 主题·圣辉象牙 ===== */
        body.theme-holy .aura { background: radial-gradient(circle at 18% 8%, #fbf8f0 0%, #f2ecdc 55%, #e2d9c2 100%); border-color: #8f96a8; box-shadow: 0 12px 30px rgba(58,44,26,.24), inset 0 0 0 1px rgba(255,255,255,.6), inset 0 0 46px rgba(90,106,138,.08); }
        body.theme-holy .head-title { color: #2e3648; text-shadow: 0 1px 0 rgba(255,255,255,.6); }
        body.theme-holy .head-sub, body.theme-holy .head-orn { color: #5a6a8a; }
        body.theme-holy .head-rule { background: linear-gradient(90deg, transparent, #5a6a8a 20%, #9ab0d4 50%, #5a6a8a 80%, transparent); }
        body.theme-holy .ult-card { background: linear-gradient(180deg, #fcfaf3, #f2eddd); border-color: #9aa0ae; border-left-color: #5a6a8a; }
        body.theme-holy .card-title { color: #2e3648; }
        body.theme-holy .p-key { color: #5a6a8a; }
        body.theme-holy .p-val { color: #2e3648; }
        body.theme-holy .p-val.desc { background: linear-gradient(180deg, rgba(90,106,138,.08), rgba(90,106,138,.03)); border-color: rgba(90,106,138,.28); }
        body.theme-holy .sec-title { color: #3e4a66; }
        body.theme-holy .sec-title::before { color: #5a6a8a; text-shadow: none; }
        body.theme-holy .sec-title::after { background: linear-gradient(90deg, rgba(90,106,138,.4), transparent); }
        body.theme-holy .uc-rim { background: linear-gradient(135deg, transparent 30%, rgba(90,106,138,.4) 50%, transparent 70%); }
        body.theme-holy .uc-glow { background: radial-gradient(circle, rgba(90,106,138,.16), transparent 66%); }
        body.theme-holy .foot { color: #5a6a8a; }
