<body class="theme-parch">
    <div class="stage">
        <div class="aura">
            <div class="theme-bar">
                <button class="theme-btn active" data-theme="parch">📜 羊皮原色</button>
                <button class="theme-btn" data-theme="royal">👑 皇权典金</button>
                <button class="theme-btn" data-theme="holy">✨ 圣辉象牙</button>
            </div>
            <div class="head">
                <div class="head-orn">─ ❖ ─</div>
                <div class="head-title">奥义觉醒</div>
                <div class="head-sub" id="headSub">史诗级 · 自悟大招</div>
                <div class="head-rule"></div>
            </div>
            <div id="ultimateContent"></div>
            <div class="foot"><span class="foot-orn">─ ❖ ─</span><span>奥义之卷 · 燃心刻印</span><span class="foot-orn">─ ❖ ─</span><span class="foot-seal">奥</span></div>
        </div>
    </div>
    <div id="rawData" style="display:none;">$1</div>

    <script>
        // ===== 工具 =====
        function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
        function firstLine(v) { return String(v == null ? '' : v).split(/\r?\n/)[0].trim(); }
        // ===== 职业系别识别（武技/魔法/神术/混合）=====
        var SYS_RULES = [
            ['mixed', ['魔剑士']],
            ['divine', ['圣光法师', '神官', '圣殿骑士', '祭司']],
            ['martial', ['战士', '骑士', '猎人', '斥候', '狂战士', '猎手']],
            ['arcane', ['元素法师', '符文师', '塑能师', '死灵法师', '召唤师', '魔导技师', '德鲁伊', '邪术师', '精灵术士', '魔兽使', '魔兽师', '魔兽']]
        ];
        function detectSys(jobRaw) {
            var j = String(jobRaw || '').replace(/[（(【\[].*?[)）】\]]/g, '');
            for (var si = 0; si < SYS_RULES.length; si++) {
                var sys = SYS_RULES[si][0], keys = SYS_RULES[si][1];
                for (var ki = 0; ki < keys.length; ki++) {
                    if (j.indexOf(keys[ki]) !== -1) return sys;
                }
            }
            return 'unknown';
        }
        var SYS_LABEL = { martial: '武技系', arcane: '魔法系', divine: '神术系', mixed: '混合系', unknown: '' };

        // ===== 解析 <奥义> 文本 → 数组 =====
        function parseUltimates(text) {
            var out = [];
            if (!text) return out;
            var parts = String(text).split(/<奥义>\s*/);
            if (parts.length === 1 && String(text).trim()) parts = ['', String(text)];
            for (var pi = 1; pi < parts.length; pi++) {
                var chunk = parts[pi].replace(/<\/奥义>\s*/g, '');
                var rec = {};
                chunk.split(/\r?\n/).forEach(function (line) {
                    line = line.trim();
                    if (!line) return;
                    var ci = line.search(/[:：]\s*/);
                    if (ci <= 0) return;
                    var k = line.slice(0, ci).trim();
                    var v = line.slice(ci + 1).trim();
                    if (k && v) rec[k] = v;
                });
                if (rec['奥义名'] || rec['描述'] || Object.keys(rec).length) out.push(rec);
            }
            return out;
        }

        // ===== 数值提取（消耗可能是纯数字或带文字）=====
        function numOf(v) {
            var m = String(v == null ? '' : v).match(/-?\d+(\.\d+)?/);
            return m ? m[0] : '';
        }

        // ===== 键值渲染：多行合并 + 数值增量高亮 =====
        function smartVal(v) {
            v = String(v == null ? '' : v).replace(/\r?\n/g, ' ');
            v = esc(v);
            v = v.replace(/(^|[\s（(；;，,、])([+-]\s*\d+)(?=$|[\s）)；;，,、])/g, function (m, pre, num) {
                return pre + '<span class="' + (/^-\s*/.test(num) ? 'down' : 'up') + '">' + esc(num) + '</span>';
            });
            return v;
        }

        // ===== 题头副标题（日期 · 地点）=====
        function buildHeadSub() {
            try {
                var stat = null;
                if (typeof Mvu !== 'undefined' && Mvu.getMvuData) stat = (Mvu.getMvuData({ type: 'message', message_id: 'latest' }) || {}).stat_data;
                var w = (stat && stat.世界) || {};
                var parts = [];
                if (w.日期) parts.push(String(w.日期));
                var loc = w.当前地点 || w.当前位置;
                if (loc) parts.push(String(loc));
                return parts.join(' · ') || '史诗级 · 自悟大招';
            } catch (e) { return '史诗级 · 自悟大招'; }
        }
        // ===== 渲染 =====
        function renderUltimates(text) {
            var list = parseUltimates(text);
            if (!list.length) return '<div class="err-msg">※ 尚未有史诗级奥义显现 ※</div>';
            var html = '';
            list.forEach(function (rec, idx) {
                var name = rec['奥义名'] || rec['名称'] || '无名奥义';
                var holder = rec['持有者'] || rec['拥有者'] || '';
                var job = rec['来源职业'] || rec['职业'] || '';
                var sys = detectSys(job);
                var css = 'ult-card sys-' + sys + ' ult-pre';
                var delay = Math.min(idx * 0.16, 0.8).toFixed(2) + 's';
                var sysTag = SYS_LABEL[sys] ? '<span class="sys-tag sys-' + sys + '">◈ ' + SYS_LABEL[sys] + '</span>' : '';
                html += '<div class="' + css + '" style="animation-delay:' + delay + '"><div class="uc-glow"></div><div class="uc-rim"></div>';
                html += '<div class="card-head"><span class="card-title">' + esc(name) + '</span>' + sysTag;
                if (holder) html += '<span class="holder-tag">👤 ' + esc(firstLine(holder)) + '</span>';
                if (job) html += '<span class="job-tag">🎖 ' + esc(firstLine(job)) + '</span>';
                html += '</div>';
                // 消耗徽章 SP / MP（0 或空值不展示，无魔力回路时 MP 常为 0）
                var sp = numOf(rec['消耗SP']), mp = numOf(rec['消耗MP']);
                if ((sp && sp !== '0') || (mp && mp !== '0')) {
                    html += '<div class="cost-row">';
                    if (sp && sp !== '0') html += '<span class="cost-chip sp">🔥 <span class="ck">SP消耗</span><b>' + esc(sp) + '</b></span>';
                    if (mp && mp !== '0') html += '<span class="cost-chip mp">💠 <span class="ck">MP消耗</span><b>' + esc(mp) + '</b></span>';
                    html += '</div>';
                }
                html += '<div class="tsplit"></div>';
                var desc = rec['描述'] || rec['效果'] || '';
                if (desc) html += '<div class="sec-title">描述</div><div class="p-val desc">' + smartVal(desc) + '</div>';
                var META = {
                    '发动': { cls: 'sec-title costsec pull', body: 'p-val desc costbody pull', tag: '发动' },
                    '代价': { cls: 'sec-title costsec toll', body: 'p-val desc costbody toll', tag: '代价' },
                    '持续时间': { cls: 'sec-title costsec dur', body: 'p-val desc costbody dur', tag: '持续时间' },
                    '限制': { cls: 'sec-title costsec lim', body: 'p-val desc costbody lim', tag: '限制' }
                };
