        // ===== 演示数据 =====
        var DEMO_TEXT = '<奥义>\n  奥义名: 煌星一斩\n  持有者: 主角\n  来源职业: 战士\n  消耗SP: 50\n  消耗MP: 0\n  描述: 将全部战意凝于剑尖，斩出横贯战场的星辉剑光，对单体目标造成毁灭性真实伤害。\n  发动: 每场战斗限1次，需消耗SP 50\n  代价: 释放后陷入1轮「力竭」状态，攻防减半\n</奥义>\n<奥义>\n  奥义名: 苍炎绝唱\n  持有者: 伊利亚·艾尔诺尔\n  来源职业: 元素法师\n  消耗SP: 20\n  消耗MP: 60\n  描述: 吟唱禁忌的苍蓝咏叹，唤起苍炎漩涡灼烧全场，持续灼烧并削减敌方MP。\n  发动: 每场战斗限1次，需消耗MP 60\n  代价: 吟唱期间无法移动，结束后魔力回路过载\n</奥义>\n';

