      if (!c || !c.worldbookSources) return;
      var purged = false;
      Object.keys(c.worldbookSources).forEach(function (u) {
        var item = c.worldbookSources[u];
        if (item && item.data && item.data.id === projectId) {
          delete c.worldbookSources[u];
