    if (touched) await saveWorldbook(wb);
    var regexArr = await loadRegex();
    var rTouched = 0;
    regexArr.forEach(function (r) {
      if (r && r.id && r.id.indexOf(REGEX_ID_PREFIX + projectId + ':') === 0) {
